export const SNIPPETS: Record<string, string> = {
  "alloc.h": "/* mtoc runtime helper: malloc wrapper that aborts on allocation\n * failure with a clear diagnostic. Used for every tensor backing\n * buffer (mtoc allocates tensor storage uniformly on the heap so the\n * codegen path is exercised by every test, not just large ones).\n *\n * `n_bytes` is the size in bytes; the call site computes\n * `numel * sizeof(double)`. Returns a non-NULL pointer or aborts.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic double *mtoc_alloc(size_t n_bytes) {\n  /* `malloc(0)` is implementation-defined: glibc returns a non-NULL\n   * sentinel, but some C libraries return NULL — which would trip\n   * the OOM abort below on a perfectly valid empty-tensor request.\n   * Clamp to a 1-byte allocation so the contract \"return non-NULL or\n   * abort on OOM\" holds uniformly. The caller never reads from a\n   * zero-element buffer, so the wasted byte is irrelevant. */\n  double *p = (double *)malloc(n_bytes == 0 ? 1 : n_bytes);\n  if (!p) {\n    fprintf(stderr, \"mtoc: out of memory (mtoc_alloc requested %zu bytes)\\n\",\n            n_bytes);\n    abort();\n  }\n  return p;\n}\n",
  "angle_real.h": "/* mtoc runtime helper: `angle(x)` for a real-scalar x.\n *\n * Mirrors numbl's `angle` real-input branch:\n *   isNaN(x)  → NaN\n *   x >= 0    → 0       (covers +0 and -0; -0 >= 0 is true in IEEE 754)\n *   else      → π\n *\n * The complex branch uses `carg(z)` directly at the call site.\n */\n\n#include <math.h>\n\nstatic double mtoc_angle_real(double x) {\n  if (isnan(x)) return x;\n  if (x >= 0.0) return 0.0;\n  return M_PI;\n}\n",
  "assert_double.h": "/* mtoc runtime helper: assert(cond) for a real-scalar condition.\n *\n * numbl's `assert(cond)` throws \"Assertion failed\" when cond is\n * boolean-false, zero, or NaN; the CLI surfaces the throw as a\n * non-zero exit. mtoc-emitted programs match by writing\n * \"Assertion failed\" to stderr and calling `exit(1)`. Success is a\n * silent no-op, so the rest of the program runs normally.\n *\n * The NaN check is explicit because C's truthiness (`if (x)`)\n * accepts NaN as truthy — numbl rejects NaN, and we want assert to\n * behave like numbl.\n */\n\n#include <math.h>\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic void mtoc_assert_double(double cond) {\n  if (cond == 0.0 || isnan(cond)) {\n    fprintf(stderr, \"Assertion failed\\n\");\n    exit(1);\n  }\n}\n",
  "assert_double_msg_text.h": "/* mtoc runtime helper: assert(cond, msg) — like mtoc_assert_double\n * but prints the user-supplied text on failure. Accepts either a\n * string or a char array via the text view; matches numbl's\n * `assert(cond, msg)` where the throw's message is the user-supplied\n * one. On the success path nothing changes — the helper neither\n * writes nor frees.\n */\n\n#include <math.h>\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic void mtoc_assert_double_msg_text(double cond, mtoc_text_view_t msg) {\n  if (cond == 0.0 || isnan(cond)) {\n    if (msg.data && msg.len > 0) {\n      fwrite(msg.data, 1, (size_t)msg.len, stderr);\n    }\n    fputc('\\n', stderr);\n    exit(1);\n  }\n}\n",
  "broadcast_dim.h": "/* mtoc runtime helper: per-axis broadcast validator.\n *\n * Returns the broadcast result of two axis sizes under MATLAB's\n * implicit-expansion rule:\n *   - a == b              → a   (same size; no expansion)\n *   - a == 1              → b   (a broadcasts to b)\n *   - b == 1              → a   (b broadcasts to a)\n *   - else                → abort (sizes are not broadcast-compatible)\n *\n * Codegen calls this once per output axis, chaining across N operands:\n *   long _mtoc_d0 = mtoc_broadcast_dim(\n *                     mtoc_broadcast_dim(A.dims[0], B.dims[0]),\n *                     C.dims[0]);\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic long mtoc_broadcast_dim(long a, long b) {\n  if (a == b) return a;\n  if (a == 1) return b;\n  if (b == 1) return a;\n  fprintf(stderr,\n    \"mtoc: shape mismatch in elementwise broadcast - \"\n    \"axis sizes %ld and %ld are not broadcast-compatible\\n\",\n    a, b);\n  abort();\n}\n",
  "cdiv.h": "/* mtoc runtime helper: complex scalar division `a / b`.\n *\n * C99's bare `/` on `double _Complex` evaluates `(ac+bd)/(c²+d²) +\n * (bc-ad)/(c²+d²)*i`, which produces `NaN + NaN*I` whenever the\n * divisor is exactly zero. numbl's interpreter takes a different\n * path: it explicitly carves out the divide-by-zero case to produce\n * signed-Inf parts (with a zero numerator part mapping to 0, not\n * NaN). That carve-out is what tests like\n * `arithmetic/test_complex_div_zero.m` exercise.\n *\n * Mirrors numbl's `complexDivide`\n * (numbl/src/numbl-core/helpers/arithmetic.ts):\n *\n *   if (bRe == 0 && bIm == 0):\n *     if (aRe == 0 && aIm == 0): return NaN + 0i\n *     return signedInf(aRe) + signedInf(aIm)*i        // 0→0, +→+Inf, -→-Inf\n *   else: Smith's algorithm (numerically stable; avoids overflow in\n *         bRe² + bIm² when one part is large).\n *\n * Codegen routes every `Div` / `ElemDiv` with at least one complex\n * operand through this helper; real operands are auto-promoted to\n * `double _Complex` at the call site via C99's implicit conversion.\n */\n\n#include <complex.h>\n#include <math.h>\n\nstatic double _Complex mtoc_cdiv(double _Complex a, double _Complex b) {\n  double ar = creal(a), ai = cimag(a);\n  double br = creal(b), bi = cimag(b);\n  if (br == 0.0 && bi == 0.0) {\n    if (ar == 0.0 && ai == 0.0) return NAN + 0.0 * I;\n    double rr = ar > 0.0 ? INFINITY : (ar < 0.0 ? -INFINITY : 0.0);\n    double ri = ai > 0.0 ? INFINITY : (ai < 0.0 ? -INFINITY : 0.0);\n    /* `rr + ri * I` would corrupt the parts: `INFINITY * I` evaluates\n     * via `Inf*(0 + 1i)` and the 0*Inf term yields NaN in the real\n     * lane. Use CMPLX() (C11) to assemble the two parts directly\n     * without arithmetic; fall back to the GCC/Clang __real__/__imag__\n     * builtins (well-defined, no aliasing) on older toolchains. */\n#if defined(CMPLX)\n    double _Complex result = CMPLX(rr, ri);\n#else\n    double _Complex result;\n    __real__ result = rr;\n    __imag__ result = ri;\n#endif\n    return result;\n  }\n  if (fabs(br) >= fabs(bi)) {\n    double r = bi / br;\n    double d = br + bi * r;\n    return ((ar + ai * r) / d) + ((ai - ar * r) / d) * I;\n  }\n  double r = br / bi;\n  double d = bi + br * r;\n  return ((ar * r + ai) / d) + ((ai * r - ar) / d) * I;\n}\n",
  "cexpm1.h": "/* mtoc runtime helper: complex expm1.\n *\n * Mirrors numbl's `complexExpm1`: expm1(z) = exp(z) - 1. C99 has no\n * `cexpm1`, so we use cexp(z) - 1 directly. (For small |z| this loses\n * precision compared to a tailored series, but numbl uses the same\n * formula — matching numbl is the byte-for-byte requirement.)\n */\n\n#include <complex.h>\n\nstatic double _Complex mtoc_cexpm1(double _Complex z) {\n  return cexp(z) - 1.0;\n}\n",
  "char_tensor.h": "/* mtoc char-tensor runtime: the C representation for every numbl char\n * array (single-quoted char-vec) that mtoc emits as multi-element.\n *\n * numbl's `char` type is a 1×N row-vector of code units. mtoc maps it\n * to one of:\n *   - bare C `char`         — for a 1×1 scalar char (no struct, no heap).\n *   - `mtoc_char_tensor_t`  — for any 1×N (N≥2) char array: a compact\n *     struct with a char buffer, shape, and an owned flag.\n *\n * The `owned` flag follows the same idiom as `mtoc_string_t`: 0 for\n * literal-pointing non-owning handles (from\n * `mtoc_char_tensor_from_literal`), 1 for heap-allocated buffers.\n * `mtoc_char_tensor_free` inspects this flag before calling `free`.\n *\n * Char arithmetic (`'A' + 1`, `'abc' + 2`) widens char elements to\n * `double` at the per-element loop site and produces a plain\n * `mtoc_tensor_t` (double) result — no mixed-type arithmetic struct.\n */\n\ntypedef struct {\n  char *data;   /* pointer to char bytes; NULL only in the empty state */\n  long rows;\n  long cols;\n  int owned;    /* 1 iff data is heap-allocated and must be free()'d */\n} mtoc_char_tensor_t;\n",
  "char_tensor_alloc.h": "/* mtoc runtime helper: allocate an uninitialized char tensor buffer.\n *\n * Returns a (rows × cols) char tensor that owns its `data` buffer.\n * The caller must eventually release it via `mtoc_char_tensor_free`\n * or `mtoc_char_tensor_assign`. Aborts with a clear diagnostic on OOM.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic mtoc_char_tensor_t mtoc_char_tensor_alloc(long rows, long cols) {\n  mtoc_char_tensor_t t;\n  long n = rows * cols;\n  t.data = (char *)malloc((size_t)(n > 0 ? n : 1));\n  if (!t.data) {\n    fprintf(stderr, \"mtoc: out of memory in mtoc_char_tensor_alloc\\n\");\n    abort();\n  }\n  t.rows = rows;\n  t.cols = cols;\n  t.owned = 1;\n  return t;\n}\n",
  "char_tensor_assign.h": "/* mtoc runtime helper: consume-and-replace assignment for char tensors.\n *\n * Frees `*lhs`'s current backing (only if owned — `mtoc_char_tensor_free`\n * checks the flag) and moves `rhs` into place. Codegen guarantees every\n * RHS is either a freshly-allocated owned handle or a literal handle\n * (owned=0 from `mtoc_char_tensor_from_literal`); both shapes are valid.\n */\n\nstatic void mtoc_char_tensor_assign(mtoc_char_tensor_t *lhs,\n                                     mtoc_char_tensor_t rhs) {\n  mtoc_char_tensor_free(lhs);\n  *lhs = rhs;\n}\n",
  "char_tensor_copy.h": "/* mtoc runtime helper: deep-copy a char tensor into a fresh heap buffer.\n *\n * Returns an owned copy of `src`. Used for `c = d;` where `d` is a\n * char-tensor variable — the copy lets `d` remain usable while giving\n * the new binding its own buffer to free independently.\n */\n\n#include <string.h>\n\nstatic mtoc_char_tensor_t mtoc_char_tensor_copy(mtoc_char_tensor_t src) {\n  long n = src.rows * src.cols;\n  mtoc_char_tensor_t out = mtoc_char_tensor_alloc(src.rows, src.cols);\n  if (n > 0 && src.data) {\n    memcpy(out.data, src.data, (size_t)n);\n  }\n  return out;\n}\n",
  "char_tensor_empty.h": "/* mtoc runtime helper: zero-initialized empty char tensor handle.\n *\n * Used at every predeclaration site so a char tensor variable starts\n * in a known state. `mtoc_char_tensor_assign` overwrites it on first\n * assignment. The empty handle has `owned = 0` so a stray free of an\n * uninitialized variable is a no-op.\n */\n\nstatic mtoc_char_tensor_t mtoc_char_tensor_empty(void) {\n  mtoc_char_tensor_t t;\n  t.data = (char *)0;\n  t.rows = 0;\n  t.cols = 0;\n  t.owned = 0;\n  return t;\n}\n",
  "char_tensor_free.h": "/* mtoc runtime helper: release a char tensor's backing buffer and reset\n * the struct to the empty state.\n *\n * The owned flag distinguishes literal-pointing handles (no free) from\n * heap-allocated ones (must free). After this call the struct matches\n * `mtoc_char_tensor_empty()`, so calling free a second time is a safe\n * no-op — useful for the scope-exit safety net at branch merges.\n */\n\n#include <stdlib.h>\n\nstatic void mtoc_char_tensor_free(mtoc_char_tensor_t *t) {\n  if (t->owned && t->data) {\n    free(t->data);\n  }\n  t->data = (char *)0;\n  t->rows = 0;\n  t->cols = 0;\n  t->owned = 0;\n}\n",
  "char_tensor_from_literal.h": "/* mtoc runtime helper: build a non-owning char tensor from a C string\n * literal in .rodata.\n *\n * Returns a 1×n handle with owned=0. `n` is the byte count of the\n * string body, excluding the trailing NUL that C string literals\n * carry. Codegen always passes a literal whose storage duration is\n * static, so the non-owning handle is safe for the program's lifetime.\n */\n\nstatic mtoc_char_tensor_t mtoc_char_tensor_from_literal(const char *src,\n                                                          long n) {\n  mtoc_char_tensor_t t;\n  t.data = (char *)src; /* discards const; we never write through it */\n  t.rows = 1;\n  t.cols = n;\n  t.owned = 0;\n  return t;\n}\n",
  "check_shape.h": "/* mtoc runtime helper: shape-mismatch trap for elementwise binary\n * ops. After the dim-lattice coarsening (one | notOne | unknown), the\n * type system no longer rejects same-category mismatches like\n * `[1 2 3] + [4 5]` at lowering — they surface here. Codegen emits one\n * `mtoc_check_shape(<source>, <other>)` per distinct non-source multi-\n * element Var on the RHS, just before the staging-buffer alloc; if any\n * pair disagrees on `rows` or `cols`, the program aborts with a clear\n * diagnostic on stderr.\n *\n * The check is once-per-assign: the loop bound below comes from\n * `<source>`, so once the source is shape-compatible with every other\n * operand, every per-element read is in bounds.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic void mtoc_check_shape(mtoc_tensor_t a, mtoc_tensor_t b) {\n  int ok = (a.ndim == b.ndim);\n  for (int i = 0; ok && i < a.ndim; i++) ok = (a.dims[i] == b.dims[i]);\n  if (ok) return;\n  /* Preserve the 2-D-style message verbatim for the common case so\n   * existing test scripts compare equal byte-for-byte; the N-D path\n   * uses a list-style format. */\n  if (a.ndim == 2 && b.ndim == 2) {\n    fprintf(stderr,\n      \"mtoc: shape mismatch in elementwise op - \"\n      \"got (%ld x %ld) and (%ld x %ld)\\n\",\n      a.dims[0], a.dims[1], b.dims[0], b.dims[1]);\n  } else {\n    fprintf(stderr, \"mtoc: shape mismatch in elementwise op - got (\");\n    for (int i = 0; i < a.ndim; i++) {\n      fprintf(stderr, i == 0 ? \"%ld\" : \"x%ld\", a.dims[i]);\n    }\n    fprintf(stderr, \") and (\");\n    for (int i = 0; i < b.ndim; i++) {\n      fprintf(stderr, i == 0 ? \"%ld\" : \"x%ld\", b.dims[i]);\n    }\n    fprintf(stderr, \")\\n\");\n  }\n  abort();\n}\n",
  "clog10.h": "/* mtoc runtime helper: complex log10.\n *\n * C99 has no `clog10`. Mirrors numbl's `complexLog10`: re = log(|z|)/ln(10),\n * im = atan2(im, re)/ln(10). Equivalent to `clog(z) / log(10)`.\n */\n\n#include <complex.h>\n#include <math.h>\n\nstatic double _Complex mtoc_clog10(double _Complex z) {\n  return clog(z) / log(10.0);\n}\n",
  "clog1p.h": "/* mtoc runtime helper: complex log1p.\n *\n * Mirrors numbl's `complexLog1p`: log1p(z) = log(1 + z). Numbl\n * delegates straight to `complexLog(1 + re, im)`, so we do the same.\n */\n\n#include <complex.h>\n\nstatic double _Complex mtoc_clog1p(double _Complex z) {\n  return clog(1.0 + z);\n}\n",
  "clog2.h": "/* mtoc runtime helper: complex log2.\n *\n * C99 has no `clog2`. Numbl computes `log2(z)` as `log(z) / ln(2)`\n * using polar form: `re = log(|z|)/ln(2)`, `im = atan2(im,re)/ln(2)`.\n * That's exactly `clog(z) / log(2)`, so we delegate.\n */\n\n#include <complex.h>\n#include <math.h>\n\nstatic double _Complex mtoc_clog2(double _Complex z) {\n  return clog(z) / log(2.0);\n}\n",
  "disp_char.h": "/* mtoc runtime helper: disp(c) for a scalar char (C `char`).\n *\n * Mirrors numbl's displayValue for a 1×1 char — prints the single\n * character as text (not as a number), followed by a newline.\n */\n\n#include <stdio.h>\n\nstatic void mtoc_disp_char(char c) {\n  putchar((unsigned char)c);\n  putchar('\\n');\n}\n",
  "disp_complex.h": "/* mtoc runtime helper: disp(z) for a complex-scalar `double _Complex`.\n *\n * Mirrors numbl's `displayValue` for the complex_number case\n * (numbl/src/numbl-core/runtime/display.ts) so cross-runner test output\n * matches. The actual formatting lives in `format_complex.h`; this\n * snippet only wraps it with a print + newline.\n */\n\n#include <stdio.h>\n#include <complex.h>\n\nstatic void mtoc_disp_complex(double _Complex z) {\n  char buf[128];\n  mtoc_format_complex(buf, sizeof(buf), z);\n  printf(\"%s\\n\", buf);\n}\n",
  "disp_double.h": "/* mtoc runtime helper: disp(x) for a real-scalar double.\n *\n * Mirrors numbl's `formatNumber` (numbl/src/numbl-core/runtime/display.ts)\n * so cross-runner test output matches. The actual formatting lives in\n * `format_double.h`; this snippet only wraps it with a print + newline.\n */\n\n#include <stdio.h>\n\nstatic void mtoc_disp_double(double x) {\n  char buf[64];\n  mtoc_format_double(buf, sizeof(buf), x);\n  printf(\"%s\\n\", buf);\n}\n",
  "disp_tensor.h": "/* mtoc runtime helper: disp(t) for a multi-element real tensor.\n *\n * Mirrors numbl's `format2DSlice` for the 2-D path and numbl's\n * page-by-page N-D rendering for `ndim > 2` (each 2-D slice prefixed\n * by a `(:,:,k2,k3,...) =` header and separated by a blank line):\n *   - elements are formatted via mtoc_format_double\n *   - each column is padded to its widest element via padStart\n *   - rows are separated by '\\n', columns by 3 spaces, 3-space indent\n *\n * Allocation: per-slice malloc for the formatted-string buffer and\n * column-width array. Both freed before the next slice. The disp\n * path is not on the hot path of typical numerical code, so the\n * simplicity is worth the alloc.\n *\n * Real-only — complex-tensor disp lives in `disp_tensor_complex.h`;\n * the lowerer dispatches on `isComplex`.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n/* Render a single 2-D slice (rows × cols) starting at `data` (the\n * caller already advanced past prior pages). Each row ends with\n * '\\n'; no leading or trailing framing — the caller adds page\n * headers / separators. */\nstatic void mtoc__disp_real_slice(const double *data, long rows, long cols) {\n  enum { CELL_CAP = 32 };\n  long ncells = rows * cols;\n  char *cells = (char *)malloc((size_t)ncells * CELL_CAP);\n  long *col_widths = (long *)calloc((size_t)cols, sizeof(long));\n  if (!cells || !col_widths) {\n    free(cells);\n    free(col_widths);\n    fprintf(stderr, \"mtoc: out of memory in mtoc_disp_tensor\\n\");\n    return;\n  }\n\n  for (long c = 0; c < cols; c++) {\n    for (long r = 0; r < rows; r++) {\n      long idx = r + c * rows;\n      char *cell = cells + idx * CELL_CAP;\n      mtoc_format_double(cell, CELL_CAP, data[idx]);\n      long len = (long)strlen(cell);\n      if (len > col_widths[c]) col_widths[c] = len;\n    }\n  }\n\n  for (long r = 0; r < rows; r++) {\n    fputs(\"   \", stdout);\n    for (long c = 0; c < cols; c++) {\n      long idx = r + c * rows;\n      char *cell = cells + idx * CELL_CAP;\n      long len = (long)strlen(cell);\n      for (long i = 0; i < col_widths[c] - len; i++) putchar(' ');\n      fputs(cell, stdout);\n      if (c < cols - 1) fputs(\"   \", stdout);\n    }\n    putchar('\\n');\n  }\n\n  free(cells);\n  free(col_widths);\n}\n\nstatic void mtoc_disp_tensor(mtoc_tensor_t t) {\n  long rows = t.ndim >= 1 ? t.dims[0] : 1;\n  long cols = t.ndim >= 2 ? t.dims[1] : 1;\n  if (rows <= 0 || cols <= 0) {\n    /* Empty tensor — match numbl's \"[]\" rendering. */\n    printf(\"[]\\n\");\n    return;\n  }\n  long page_size = rows * cols;\n  long num_pages = 1;\n  for (int i = 2; i < t.ndim; i++) num_pages *= t.dims[i];\n\n  for (long p = 0; p < num_pages; p++) {\n    if (t.ndim > 2) {\n      /* Blank line between pages (after the previous slice's trailing\n       * '\\n'). For the very first page there is no leading separator. */\n      if (p > 0) putchar('\\n');\n      /* Outer indices via column-major ind2sub (k2 changes fastest). */\n      long rem = p;\n      fputs(\"(:,:\", stdout);\n      for (int i = 2; i < t.ndim; i++) {\n        long d = t.dims[i];\n        long s = rem % d;\n        rem /= d;\n        printf(\",%ld\", s + 1);\n      }\n      fputs(\") =\\n\\n\", stdout);\n    }\n    mtoc__disp_real_slice(t.real + p * page_size, rows, cols);\n  }\n}\n",
  "disp_tensor_complex.h": "/* mtoc runtime helper: disp(t) for a multi-element complex tensor.\n *\n * Mirrors numbl's `format2DSlice` for the isComplex==true branch\n * (numbl/src/numbl-core/runtime/display.ts):\n *   - elements are formatted via `mtoc_format_complex` over the\n *     `(real[idx], imag[idx])` pair (constructed as `re + im*I`)\n *   - each column is padded to its widest element via padStart\n *   - rows are separated by '\\n', columns by 3 spaces, 3-space indent\n *\n * For `ndim > 2`, dispatches page-by-page exactly like\n * `mtoc_disp_tensor`: a `(:,:,k2,k3,...) =` header per slice and\n * blank-line separation between slices. Real-tensor disp lives in\n * `disp_tensor.h`; the codegen dispatcher picks one based on the\n * tensor's static `isComplex`.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <complex.h>\n\n/* Render a single 2-D complex slice (rows × cols) starting at the\n * given real / imag pointers (caller advances past prior pages). */\nstatic void mtoc__disp_complex_slice(\n  const double *re, const double *im, long rows, long cols\n) {\n  /* CELL_CAP is sized for \"<re> + <im>i\" at 4-digit precision, plus\n   * scientific-notation slack and the trailing 'i'. 64 is comfortable. */\n  enum { CELL_CAP = 64 };\n  long ncells = rows * cols;\n  char *cells = (char *)malloc((size_t)ncells * CELL_CAP);\n  long *col_widths = (long *)calloc((size_t)cols, sizeof(long));\n  if (!cells || !col_widths) {\n    free(cells);\n    free(col_widths);\n    fprintf(stderr, \"mtoc: out of memory in mtoc_disp_tensor_complex\\n\");\n    return;\n  }\n\n  for (long c = 0; c < cols; c++) {\n    for (long r = 0; r < rows; r++) {\n      long idx = r + c * rows;\n      char *cell = cells + idx * CELL_CAP;\n      double _Complex z = re[idx] + im[idx] * I;\n      mtoc_format_complex(cell, CELL_CAP, z);\n      long len = (long)strlen(cell);\n      if (len > col_widths[c]) col_widths[c] = len;\n    }\n  }\n\n  for (long r = 0; r < rows; r++) {\n    fputs(\"   \", stdout);\n    for (long c = 0; c < cols; c++) {\n      long idx = r + c * rows;\n      char *cell = cells + idx * CELL_CAP;\n      long len = (long)strlen(cell);\n      for (long i = 0; i < col_widths[c] - len; i++) putchar(' ');\n      fputs(cell, stdout);\n      if (c < cols - 1) fputs(\"   \", stdout);\n    }\n    putchar('\\n');\n  }\n\n  free(cells);\n  free(col_widths);\n}\n\nstatic void mtoc_disp_tensor_complex(mtoc_tensor_t t) {\n  long rows = t.ndim >= 1 ? t.dims[0] : 1;\n  long cols = t.ndim >= 2 ? t.dims[1] : 1;\n  if (rows <= 0 || cols <= 0) {\n    /* Empty tensor — match numbl's \"[]\" rendering. */\n    printf(\"[]\\n\");\n    return;\n  }\n  long page_size = rows * cols;\n  long num_pages = 1;\n  for (int i = 2; i < t.ndim; i++) num_pages *= t.dims[i];\n\n  for (long p = 0; p < num_pages; p++) {\n    if (t.ndim > 2) {\n      if (p > 0) putchar('\\n');\n      long rem = p;\n      fputs(\"(:,:\", stdout);\n      for (int i = 2; i < t.ndim; i++) {\n        long d = t.dims[i];\n        long s = rem % d;\n        rem /= d;\n        printf(\",%ld\", s + 1);\n      }\n      fputs(\") =\\n\\n\", stdout);\n    }\n    mtoc__disp_complex_slice(\n      t.real + p * page_size, t.imag + p * page_size, rows, cols\n    );\n  }\n}\n",
  "disp_text.h": "/* mtoc runtime helper: disp on a text view.\n *\n * Mirrors numbl's `displayValue` for string / char-array — the raw\n * bytes followed by a newline. Empty input prints just the newline.\n * Bytes are written verbatim through stdout so UTF-8 sequences pass\n * through cleanly. Used for both `disp(\"hi\")` (string) and\n * `disp('hi')` (char array) — the caller wraps either source in\n * `mtoc_text_from_string` / `mtoc_text_from_char_tensor`.\n */\n\n#include <stdio.h>\n\nstatic void mtoc_disp_text(mtoc_text_view_t t) {\n  if (t.data && t.len > 0) {\n    fwrite(t.data, 1, (size_t)t.len, stdout);\n  }\n  putchar('\\n');\n}\n",
  "error_text.h": "/* mtoc runtime helper: error(msg) — raise a runtime error and abort.\n *\n * numbl's `error(s)` throws a RuntimeError; the host harness prints\n * the message and exits non-zero. mtoc-emitted programs match by\n * writing the message to stderr (no special framing) and calling\n * `exit(1)`. Accepts either a string or a char array via the text\n * view; numbl's `error(id, fmt, ...)` shapes are deferred at lowering.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic void mtoc_error_text(mtoc_text_view_t t) {\n  if (t.data && t.len > 0) {\n    fwrite(t.data, 1, (size_t)t.len, stderr);\n  }\n  fputc('\\n', stderr);\n  exit(1);\n}\n",
  "format_complex.h": "/* mtoc runtime helper: format a `double _Complex` value the same way\n * numbl's `formatComplex` does (numbl/src/numbl-core/runtime/display.ts),\n * into a caller-provided buffer.\n *\n * Branches mirror numbl exactly:\n *   - im == 0          → `<formatNumber(re)>`           (real-format path)\n *   - re == 0          → `<formatNumber(im)>i`          (pure imaginary)\n *   - im < 0           → `<formatNumber(re)> - <formatNumber(-im)>i`\n *   - else             → `<formatNumber(re)> + <formatNumber(im)>i`\n *\n * The spaces around the sign separator are part of the format and are\n * load-bearing for byte-for-byte cross-runner output.\n *\n * Returns the number of characters written (excluding trailing NUL),\n * matching `mtoc_format_double`'s contract.\n */\n\n#include <stdio.h>\n#include <complex.h>\n\nstatic int mtoc_format_complex(char *out, size_t cap, double _Complex z) {\n  double re = creal(z);\n  double im = cimag(z);\n  if (im == 0.0) {\n    return mtoc_format_double(out, cap, re);\n  }\n  char re_buf[64];\n  char im_buf[64];\n  if (re == 0.0) {\n    mtoc_format_double(im_buf, sizeof(im_buf), im);\n    return snprintf(out, cap, \"%si\", im_buf);\n  }\n  mtoc_format_double(re_buf, sizeof(re_buf), re);\n  if (im < 0.0) {\n    mtoc_format_double(im_buf, sizeof(im_buf), -im);\n    return snprintf(out, cap, \"%s - %si\", re_buf, im_buf);\n  }\n  mtoc_format_double(im_buf, sizeof(im_buf), im);\n  return snprintf(out, cap, \"%s + %si\", re_buf, im_buf);\n}\n",
  "format_double.h": "/* mtoc runtime helper: format a double the same way numbl's\n * `formatNumber` does, into a caller-provided buffer.\n *\n * Used by both scalar and tensor disp so cross-runner output matches\n * numbl byte-for-byte. Kept in its own snippet so disp_double.h and\n * disp_tensor.h can pull it in via the snippet dependency mechanism.\n *\n * Returns the number of characters written (excluding trailing NUL).\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n\nstatic int mtoc_format_double(char *out, size_t cap, double x) {\n  if (isnan(x)) return snprintf(out, cap, \"NaN\");\n  if (isinf(x)) return snprintf(out, cap, x > 0 ? \"Infinity\" : \"-Infinity\");\n  if (x == 0.0) x = 0.0; /* normalize -0 */\n\n  if (fabs(x) < 1e15 && x == (double)(long long)x) {\n    return snprintf(out, cap, \"%lld\", (long long)x);\n  }\n\n  char buf[64];\n  snprintf(buf, sizeof(buf), \"%.4e\", x);\n  char *e_p = strchr(buf, 'e');\n  if (!e_p) return snprintf(out, cap, \"%s\", buf);\n  int dec_exp = atoi(e_p + 1);\n\n  if (dec_exp < -6 || dec_exp >= 5) {\n    /* Scientific. Strip trailing zeros from mantissa, drop leading\n       zeros from the exponent, but keep its sign. */\n    char *m_end = e_p - 1;\n    while (m_end > buf && *m_end == '0') m_end--;\n    if (m_end >= buf && *m_end == '.') m_end--;\n    char *exp_p = e_p + 1;\n    char sign = '+';\n    if (*exp_p == '+' || *exp_p == '-') { sign = *exp_p; exp_p++; }\n    while (*exp_p == '0' && *(exp_p + 1) != '\\0') exp_p++;\n    return snprintf(out, cap, \"%.*se%c%s\",\n                    (int)(m_end - buf + 1), buf, sign, exp_p);\n  }\n\n  int frac_digits = 4 - dec_exp;\n  if (frac_digits < 0) frac_digits = 0;\n  snprintf(buf, sizeof(buf), \"%.*f\", frac_digits, x);\n  if (strchr(buf, '.')) {\n    size_t len = strlen(buf);\n    while (len > 0 && buf[len - 1] == '0') len--;\n    if (len > 0 && buf[len - 1] == '.') len--;\n    buf[len] = '\\0';\n  }\n  return snprintf(out, cap, \"%s\", buf);\n}\n",
  "format_engine.h": "/* mtoc runtime: numbl-compatible format engine shared by fprintf and\n * sprintf.\n *\n * Mirrors numbl's `sprintfFormat`\n * (numbl/src/numbl-core/helpers/string.ts) byte-for-byte:\n *   - spec set: d i u f e E g G x X o s c %\n *   - flags  - + 0 # space; precision `.N`; width digits; `*` consumes\n *     the next numeric arg as a width\n *   - escapes \\n \\t \\\\ interpreted AT FORMAT TIME (matching the numbl\n *     lexer, which preserves backslash bytes verbatim)\n *   - numeric tensors flatten column-major into the scalar stream;\n *     format string cycles through the args until the stream is\n *     exhausted (with a \"no arg consumed this pass\" guard against\n *     infinite output)\n *\n * Output goes through a caller-supplied `mtoc__writer_fn` callback so\n * the same walker drives fprintf (FILE* sink) and sprintf (growable-\n * buffer sink).\n *\n * Argument transport: each call hands the walker an array of\n * `mtoc_fprintf_arg_t` (a tagged union). The codegen builds the array\n * at the call site via a C99 compound literal, keeping the call shape\n * a single C expression even for variadic arities.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n#include <complex.h>\n\n/* Tag identifying the payload variant of a single mtoc_fprintf_arg_t.\n * Values are stable — the engine switches on them. */\nenum {\n  MTOC_FA_DOUBLE = 1,\n  MTOC_FA_COMPLEX = 2,\n  MTOC_FA_TEXT = 3,\n  MTOC_FA_TENSOR = 4   /* real OR complex tensor; engine probes .imag */\n};\n\ntypedef struct {\n  int kind;\n  union {\n    double d;\n    double _Complex z;\n    mtoc_text_view_t t;\n    const mtoc_tensor_t *tensor;\n  } u;\n} mtoc_fprintf_arg_t;\n\n/* Per-slot value handed to one format spec, after expanding any\n * tensor argument into its flattened element stream. */\ntypedef struct {\n  int kind;           /* MTOC_FA_DOUBLE / _COMPLEX / _TEXT */\n  double d;\n  double _Complex z;\n  mtoc_text_view_t t;\n} mtoc__slot_t;\n\n/* Iterator state over the (tagged) arg array with lazy column-major\n * tensor flattening. */\ntypedef struct {\n  const mtoc_fprintf_arg_t *args;\n  int nargs;\n  int arg_idx;             /* next un-touched entry of args[] */\n  int in_tensor;           /* 1 iff currently iterating a flattened tensor */\n  const mtoc_tensor_t *cur_t;\n  long t_idx;\n  long t_count;\n} mtoc__arg_iter_t;\n\ntypedef void (*mtoc__writer_fn)(void *ctx, const char *bytes, long len);\n\n/* Advance the iterator to the next scalar slot. Returns 0 when no\n * more slots are available (caller stops cycling). */\nstatic int mtoc__next_slot(mtoc__arg_iter_t *it, mtoc__slot_t *out) {\n  while (1) {\n    if (it->in_tensor) {\n      if (it->t_idx >= it->t_count) {\n        it->in_tensor = 0;\n        it->cur_t = (const mtoc_tensor_t *)0;\n        continue;\n      }\n      const mtoc_tensor_t *t = it->cur_t;\n      long i = it->t_idx++;\n      if (t->imag) {\n        out->kind = MTOC_FA_COMPLEX;\n        out->z = t->real[i] + t->imag[i] * I;\n      } else {\n        out->kind = MTOC_FA_DOUBLE;\n        out->d = t->real[i];\n      }\n      return 1;\n    }\n    if (it->arg_idx >= it->nargs) return 0;\n    const mtoc_fprintf_arg_t *a = &it->args[it->arg_idx++];\n    switch (a->kind) {\n      case MTOC_FA_DOUBLE:\n        out->kind = MTOC_FA_DOUBLE;\n        out->d = a->u.d;\n        return 1;\n      case MTOC_FA_COMPLEX:\n        out->kind = MTOC_FA_COMPLEX;\n        out->z = a->u.z;\n        return 1;\n      case MTOC_FA_TEXT:\n        out->kind = MTOC_FA_TEXT;\n        out->t = a->u.t;\n        return 1;\n      case MTOC_FA_TENSOR: {\n        const mtoc_tensor_t *t = a->u.tensor;\n        long n = 1;\n        for (int k = 0; k < t->ndim; k++) n *= t->dims[k];\n        if (n <= 0) continue;   /* empty tensor — skip */\n        it->in_tensor = 1;\n        it->cur_t = t;\n        it->t_idx = 0;\n        it->t_count = n;\n        break;\n      }\n      default:\n        return 0;\n    }\n  }\n}\n\n/* True iff the iterator has any remaining slot. */\nstatic int mtoc__iter_has_more(const mtoc__arg_iter_t *it) {\n  if (it->in_tensor && it->t_idx < it->t_count) return 1;\n  if (it->arg_idx < it->nargs) return 1;\n  return 0;\n}\n\n/* Number of slots consumed so far — used to detect a no-progress\n * pass over a format with no specs. */\nstatic long mtoc__iter_consumed(const mtoc__arg_iter_t *it) {\n  /* arg_idx counts args fully consumed; if inside a tensor, t_idx\n   * counts elements of the current tensor already produced. */\n  long n = (long)it->arg_idx;\n  if (it->in_tensor) n = (long)(it->arg_idx - 1) + (long)it->t_idx;\n  /* Above formula is monotonic across calls, which is all the caller\n   * needs (it just compares the value to a snapshot from the start\n   * of the pass). */\n  return n;\n}\n\n/* Emit a small byte buffer through the writer. */\nstatic void mtoc__emit_bytes(mtoc__writer_fn writer, void *ctx,\n                             const char *bytes, long len) {\n  if (len > 0) writer(ctx, bytes, len);\n}\n\n/* Emit a NUL-terminated C string through the writer. */\nstatic void mtoc__emit_cstr(mtoc__writer_fn writer, void *ctx, const char *s) {\n  mtoc__emit_bytes(writer, ctx, s, (long)strlen(s));\n}\n\n/* Append numbl's `applyWidth` semantics: pad `s` (length `slen`) to\n * `width` using `pad_char` (' ' or '0'), respecting left-align. */\nstatic void mtoc__emit_padded(mtoc__writer_fn writer, void *ctx,\n                              const char *s, long slen,\n                              long width, char pad_char, int left_align) {\n  if (width <= slen) {\n    mtoc__emit_bytes(writer, ctx, s, slen);\n    return;\n  }\n  long pad_len = width - slen;\n  if (left_align) {\n    mtoc__emit_bytes(writer, ctx, s, slen);\n    for (long i = 0; i < pad_len; i++) writer(ctx, \" \", 1);\n  } else {\n    for (long i = 0; i < pad_len; i++) writer(ctx, &pad_char, 1);\n    mtoc__emit_bytes(writer, ctx, s, slen);\n  }\n}\n\n/* Parse the spec body (between '%' and the type char) — fills\n * `width` (0 if absent), `prec` (-1 if absent), and the flag set.\n * Resolves '*' for width by consuming one numeric slot via the\n * iterator. Returns 1 on success, 0 if the iterator ran out while\n * resolving '*'. */\nstatic int mtoc__parse_spec(const char *spec, long spec_len,\n                            mtoc__arg_iter_t *it,\n                            long *out_width, int *out_prec,\n                            int *out_has_plus, int *out_has_space,\n                            int *out_left_align, int *out_zero_pad) {\n  long width = 0;\n  int prec = -1;\n  int has_plus = 0, has_space = 0, left_align = 0, zero_pad = 0;\n  int in_prec = 0;\n  /* spec begins with '%'; iterate over its body. */\n  for (long i = 1; i < spec_len; i++) {\n    char c = spec[i];\n    if (in_prec) {\n      if (c >= '0' && c <= '9') {\n        if (prec < 0) prec = 0;\n        prec = prec * 10 + (c - '0');\n        continue;\n      }\n      in_prec = 0;\n    }\n    if (c == '.') {\n      in_prec = 1;\n      prec = 0;\n      continue;\n    }\n    if (c == '-') { left_align = 1; continue; }\n    if (c == '+') { has_plus = 1; continue; }\n    if (c == ' ') { has_space = 1; continue; }\n    if (c == '#') { /* parsed but no behavior */ continue; }\n    if (c == '0' && width == 0) { zero_pad = 1; continue; }\n    if (c >= '0' && c <= '9') {\n      width = width * 10 + (c - '0');\n      continue;\n    }\n    if (c == '*') {\n      /* `*` width: consume one numeric slot from the iterator. */\n      mtoc__slot_t slot;\n      if (!mtoc__next_slot(it, &slot)) return 0;\n      double v = (slot.kind == MTOC_FA_DOUBLE) ? slot.d\n               : (slot.kind == MTOC_FA_COMPLEX) ? creal(slot.z) : 0.0;\n      long n = (long)floor(v + 0.5);\n      width = n > 0 ? n : 0;  /* * resolves to the arg value; negative collapses to 0 */\n      continue;\n    }\n    /* Anything else is unexpected — numbl carries it through\n     * applyWidth as part of the spec text. We ignore it for width\n     * but it has no other effect. */\n  }\n  if (zero_pad && left_align) zero_pad = 0;   /* numbl's rule */\n  *out_width = width;\n  *out_prec = prec;\n  *out_has_plus = has_plus;\n  *out_has_space = has_space;\n  *out_left_align = left_align;\n  *out_zero_pad = zero_pad;\n  return 1;\n}\n\n/* Format a real number as JS `String(n)` would — used by %s on a\n * numeric arg (numbl's `toString` path). Handles NaN / +-Inf and\n * defers to `%g` shortened representation for finite values. */\nstatic long mtoc__num_to_str(char *buf, size_t cap, double x) {\n  if (isnan(x)) return (long)snprintf(buf, cap, \"NaN\");\n  if (isinf(x)) return (long)snprintf(buf, cap, x > 0 ? \"Infinity\" : \"-Infinity\");\n  /* Integer-valued doubles in the safe-integer range render without\n   * a decimal point — matches `String(n)` exactly. */\n  if (fabs(x) < 1e16 && x == (double)(long long)x) {\n    return (long)snprintf(buf, cap, \"%lld\", (long long)x);\n  }\n  /* For non-integers, use shortest-round-trip \"%.17g\" then trim. */\n  long n = (long)snprintf(buf, cap, \"%.17g\", x);\n  return n;\n}\n\n/* Emit one `\\` escape sequence — numbl interprets only \\n, \\t, \\\\\n * at format time; any other `\\x` passes through verbatim. */\nstatic long mtoc__emit_escape(mtoc__writer_fn writer, void *ctx,\n                               char next) {\n  switch (next) {\n    case 'n': writer(ctx, \"\\n\", 1); return 1;\n    case 't': writer(ctx, \"\\t\", 1); return 1;\n    case '\\\\': writer(ctx, \"\\\\\", 1); return 1;\n    default: {\n      char buf[2] = { '\\\\', next };\n      writer(ctx, buf, 2);\n      return 1;\n    }\n  }\n}\n\n/* Emit a %d / %i / %u slot. Mirrors numbl's int branch exactly:\n *   - non-integer (or negative for %u) → fall back to %e prec=6\n *     with 2-digit-padded exponent.\n *   - otherwise render |x| as decimal, prepend sign per flags,\n *     and apply width/zero-pad. */\nstatic void mtoc__emit_int(mtoc__writer_fn writer, void *ctx,\n                            const char *spec, long spec_len,\n                            mtoc__arg_iter_t *it, char type_ch,\n                            double raw) {\n  int is_int = isfinite(raw) && raw == (double)(long long)raw\n               && fabs(raw) < 1e18;\n  int can_int = is_int;\n  if (type_ch == 'u' && raw < 0.0) can_int = 0;\n  long width;\n  int prec, has_plus, has_space, left_align, zero_pad;\n  if (!mtoc__parse_spec(spec, spec_len, it,\n                        &width, &prec, &has_plus, &has_space,\n                        &left_align, &zero_pad)) {\n    return;\n  }\n  if (!can_int) {\n    /* Non-int (or %u negative) — render as %e prec 6 with 2-digit exp. */\n    char ebuf[64];\n    long elen = (long)snprintf(ebuf, sizeof(ebuf), \"%.*e\",\n                                prec >= 0 ? prec : 6, raw);\n    /* Pad exponent to ≥2 digits (numbl rule). */\n    /* Look for 'e[+-]<digit>$'. */\n    if (elen >= 3) {\n      char *e = strchr(ebuf, 'e');\n      if (e && (e[1] == '+' || e[1] == '-') &&\n          e[2] >= '0' && e[2] <= '9' && e[3] == '\\0') {\n        char tail = e[2];\n        e[2] = '0';\n        e[3] = tail;\n        e[4] = '\\0';\n        elen++;\n      }\n    }\n    mtoc__emit_padded(writer, ctx, ebuf, elen, width,\n                      zero_pad ? '0' : ' ', left_align);\n    return;\n  }\n  /* Integer formatting. */\n  char ibuf[32];\n  long long n_int = (long long)raw;\n  long ilen = (long)snprintf(ibuf, sizeof(ibuf), \"%lld\",\n                              n_int < 0 ? -n_int : n_int);\n  char sign_ch = 0;\n  if (n_int < 0) sign_ch = '-';\n  else if (has_plus) sign_ch = '+';\n  else if (has_space) sign_ch = ' ';\n  long sign_len = sign_ch ? 1 : 0;\n  long total = sign_len + ilen;\n  if (width <= total) {\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    mtoc__emit_bytes(writer, ctx, ibuf, ilen);\n    return;\n  }\n  long pad = width - total;\n  if (left_align) {\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    mtoc__emit_bytes(writer, ctx, ibuf, ilen);\n    for (long i = 0; i < pad; i++) writer(ctx, \" \", 1);\n  } else if (zero_pad) {\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    for (long i = 0; i < pad; i++) writer(ctx, \"0\", 1);\n    mtoc__emit_bytes(writer, ctx, ibuf, ilen);\n  } else {\n    for (long i = 0; i < pad; i++) writer(ctx, \" \", 1);\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    mtoc__emit_bytes(writer, ctx, ibuf, ilen);\n  }\n}\n\n/* Emit %f / %e / %E / %g / %G slot — defers to snprintf for the\n * numeric body, applies sign-prefix and width afterwards. */\nstatic void mtoc__emit_float(mtoc__writer_fn writer, void *ctx,\n                              const char *spec, long spec_len,\n                              mtoc__arg_iter_t *it, char type_ch,\n                              double x) {\n  long width;\n  int prec, has_plus, has_space, left_align, zero_pad;\n  if (!mtoc__parse_spec(spec, spec_len, it,\n                        &width, &prec, &has_plus, &has_space,\n                        &left_align, &zero_pad)) {\n    return;\n  }\n  if (!isfinite(x)) {\n    const char *s = isnan(x) ? \"NaN\" : (x > 0 ? \"Infinity\" : \"-Infinity\");\n    long slen = (long)strlen(s);\n    /* zero-padding is meaningless for NaN/Inf — always use spaces */\n    mtoc__emit_padded(writer, ctx, s, slen, width, ' ', left_align);\n    return;\n  }\n  int default_prec = 6;\n  if (prec < 0) prec = default_prec;\n\n  char buf[96];\n  long len = 0;\n  if (type_ch == 'f') {\n    len = (long)snprintf(buf, sizeof(buf), \"%.*f\", prec, fabs(x));\n  } else if (type_ch == 'e' || type_ch == 'E') {\n    len = (long)snprintf(buf, sizeof(buf), \"%.*e\", prec, fabs(x));\n    /* Pad exponent to ≥2 digits. */\n    char *e = strchr(buf, 'e');\n    if (e && (e[1] == '+' || e[1] == '-') &&\n        e[2] >= '0' && e[2] <= '9' && e[3] == '\\0') {\n      char tail = e[2];\n      e[2] = '0';\n      e[3] = tail;\n      e[4] = '\\0';\n      len++;\n    }\n    if (type_ch == 'E') {\n      for (long i = 0; i < len; i++) {\n        if (buf[i] == 'e') buf[i] = 'E';\n      }\n    }\n  } else {\n    /* %g / %G — C-style: %e if exp < -4 or >= prec, else %f stripped. */\n    int gprec = prec > 0 ? prec : 1;\n    if (x == 0.0) {\n      buf[0] = '0';\n      buf[1] = '\\0';\n      len = 1;\n    } else {\n      double ax = fabs(x);\n      int exp10 = (int)floor(log10(ax));\n      if (exp10 < -4 || exp10 >= gprec) {\n        len = (long)snprintf(buf, sizeof(buf), \"%.*e\", gprec - 1, ax);\n        /* Strip trailing zeros from mantissa, then pad exp ≥2 digits. */\n        char *e = strchr(buf, 'e');\n        if (e) {\n          char *m_end = e - 1;\n          while (m_end > buf && *m_end == '0') m_end--;\n          if (m_end > buf && *m_end == '.') m_end--;\n          /* Shift exponent down to right after the mantissa. */\n          long m_keep = m_end - buf + 1;\n          long e_len = (long)strlen(e);\n          memmove(buf + m_keep, e, (size_t)e_len + 1);\n          len = m_keep + e_len;\n          /* Pad exp ≥2 digits. */\n          e = buf + m_keep;\n          if ((e[1] == '+' || e[1] == '-') &&\n              e[2] >= '0' && e[2] <= '9' && e[3] == '\\0') {\n            char tail = e[2];\n            e[2] = '0';\n            e[3] = tail;\n            e[4] = '\\0';\n            len++;\n          }\n        }\n      } else {\n        /* Fixed notation — emulate JS Number.prototype.toPrecision\n         * with trailing-zero strip. */\n        int frac = gprec - 1 - exp10;\n        if (frac < 0) frac = 0;\n        len = (long)snprintf(buf, sizeof(buf), \"%.*f\", frac, ax);\n        if (strchr(buf, '.')) {\n          while (len > 0 && buf[len - 1] == '0') len--;\n          if (len > 0 && buf[len - 1] == '.') len--;\n          buf[len] = '\\0';\n        }\n      }\n    }\n    if (type_ch == 'G') {\n      for (long i = 0; i < len; i++) {\n        if (buf[i] >= 'a' && buf[i] <= 'z') buf[i] = (char)(buf[i] - 32);\n      }\n    }\n  }\n  /* Apply sign prefix and width. */\n  char sign_ch = 0;\n  if (x < 0.0 && type_ch == 'f') sign_ch = '-';\n  else if (x < 0.0) sign_ch = '-';\n  else if (has_plus) sign_ch = '+';\n  else if (has_space) sign_ch = ' ';\n  long sign_len = sign_ch ? 1 : 0;\n  long total = sign_len + len;\n  if (width <= total) {\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    mtoc__emit_bytes(writer, ctx, buf, len);\n    return;\n  }\n  long pad = width - total;\n  if (left_align) {\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    mtoc__emit_bytes(writer, ctx, buf, len);\n    for (long i = 0; i < pad; i++) writer(ctx, \" \", 1);\n  } else if (zero_pad) {\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    for (long i = 0; i < pad; i++) writer(ctx, \"0\", 1);\n    mtoc__emit_bytes(writer, ctx, buf, len);\n  } else {\n    for (long i = 0; i < pad; i++) writer(ctx, \" \", 1);\n    if (sign_ch) writer(ctx, &sign_ch, 1);\n    mtoc__emit_bytes(writer, ctx, buf, len);\n  }\n}\n\n/* Emit %x / %X / %o — round-to-int absolute value, then convert. */\nstatic void mtoc__emit_xo(mtoc__writer_fn writer, void *ctx,\n                          const char *spec, long spec_len,\n                          mtoc__arg_iter_t *it, char type_ch,\n                          double raw) {\n  long width;\n  int prec, has_plus, has_space, left_align, zero_pad;\n  if (!mtoc__parse_spec(spec, spec_len, it,\n                        &width, &prec, &has_plus, &has_space,\n                        &left_align, &zero_pad)) {\n    return;\n  }\n  long long n = (long long)floor(fabs(raw) + 0.5);\n  char buf[32];\n  long len = 0;\n  if (type_ch == 'o') {\n    len = (long)snprintf(buf, sizeof(buf), \"%llo\", n);\n  } else {\n    len = (long)snprintf(buf, sizeof(buf), \"%llx\", n);\n    if (type_ch == 'X') {\n      for (long i = 0; i < len; i++) {\n        if (buf[i] >= 'a' && buf[i] <= 'f') buf[i] = (char)(buf[i] - 32);\n      }\n    }\n  }\n  mtoc__emit_padded(writer, ctx, buf, len, width,\n                    zero_pad ? '0' : ' ', left_align);\n}\n\n/* Emit %s — text view (string or char-array) goes through verbatim;\n * a numeric slot routes through `String(n)` semantics. */\nstatic void mtoc__emit_s(mtoc__writer_fn writer, void *ctx,\n                         const char *spec, long spec_len,\n                         mtoc__arg_iter_t *it, const mtoc__slot_t *slot) {\n  long width;\n  int prec, has_plus, has_space, left_align, zero_pad;\n  if (!mtoc__parse_spec(spec, spec_len, it,\n                        &width, &prec, &has_plus, &has_space,\n                        &left_align, &zero_pad)) {\n    return;\n  }\n  const char *data = (const char *)0;\n  long slen = 0;\n  char numbuf[64];\n  if (slot->kind == MTOC_FA_TEXT) {\n    data = slot->t.data;\n    slen = slot->t.len > 0 ? slot->t.len : 0;\n  } else if (slot->kind == MTOC_FA_DOUBLE) {\n    slen = mtoc__num_to_str(numbuf, sizeof(numbuf), slot->d);\n    data = numbuf;\n  } else {\n    /* Complex %s — render as \"<re>+<im>i\" via the existing format helper. */\n    char cbuf[128];\n    long n = (long)mtoc_format_complex(cbuf, sizeof(cbuf), slot->z);\n    if (n < 0) n = 0;\n    if (n > (long)sizeof(cbuf)) n = (long)sizeof(cbuf);\n    mtoc__emit_padded(writer, ctx, cbuf, n, width, ' ', left_align);\n    return;\n  }\n  mtoc__emit_padded(writer, ctx, data, slen, width, ' ', left_align);\n}\n\n/* The main walker. Loops over `fmt` consuming args; cycles through\n * the format string until the arg stream is exhausted, with a\n * \"made no progress this pass\" guard against infinite output on a\n * format with no `%` specifiers. */\nstatic void mtoc__format_walk(mtoc__writer_fn writer, void *ctx,\n                              mtoc_text_view_t fmt,\n                              int nargs, const mtoc_fprintf_arg_t *args) {\n  mtoc__arg_iter_t it;\n  it.args = args;\n  it.nargs = nargs;\n  it.arg_idx = 0;\n  it.in_tensor = 0;\n  it.cur_t = (const mtoc_tensor_t *)0;\n  it.t_idx = 0;\n  it.t_count = 0;\n\n  long fmt_len = fmt.len > 0 ? fmt.len : 0;\n  if (fmt_len == 0 || !fmt.data) return;\n\n  do {\n    long start_consumed = mtoc__iter_consumed(&it);\n    long i = 0;\n    int out_of_args = 0;\n    while (i < fmt_len && !out_of_args) {\n      char c = fmt.data[i];\n      if (c == '%' && i + 1 < fmt_len) {\n        long spec_start = i;\n        i++;\n        while (i < fmt_len &&\n               !strchr(\"dfigeEsoxXuc%\", fmt.data[i])) {\n          i++;\n        }\n        if (i >= fmt_len) {\n          /* Spec body ran to end-of-string with no recognized type\n           * char (e.g. `'%G\\n'` — numbl's inner spec-end set is\n           * `\"dfigeEsoxXuc%\"`, no uppercase G). Numbl emits nothing\n           * here and stops the pass without consuming an arg; mtoc\n           * matches for byte-for-byte parity. */\n          break;\n        }\n        char type_ch = fmt.data[i++];\n        long spec_len = i - 1 - spec_start;   /* exclude type char */\n        const char *spec = fmt.data + spec_start;\n        if (type_ch == '%') {\n          writer(ctx, \"%\", 1);\n          continue;\n        }\n        mtoc__slot_t slot;\n        if (!mtoc__next_slot(&it, &slot)) {\n          out_of_args = 1;\n          break;\n        }\n        double dval = (slot.kind == MTOC_FA_DOUBLE) ? slot.d\n                    : (slot.kind == MTOC_FA_COMPLEX) ? creal(slot.z)\n                    : 0.0;\n        switch (type_ch) {\n          case 'd':\n          case 'i':\n          case 'u':\n            mtoc__emit_int(writer, ctx, spec, spec_len, &it,\n                            type_ch, dval);\n            break;\n          case 'f':\n          case 'e':\n          case 'E':\n          case 'g':\n          case 'G':\n            mtoc__emit_float(writer, ctx, spec, spec_len, &it,\n                              type_ch, dval);\n            break;\n          case 'x':\n          case 'X':\n          case 'o':\n            mtoc__emit_xo(writer, ctx, spec, spec_len, &it,\n                          type_ch, dval);\n            break;\n          case 's':\n            mtoc__emit_s(writer, ctx, spec, spec_len, &it, &slot);\n            break;\n          case 'c': {\n            int code = (int)floor(dval + 0.5);\n            if (code < 0) code = 0;\n            if (code > 0x10FFFF) code = 0;\n            /* Emit as a single byte for code points <128, else as a\n             * minimal UTF-8 sequence so non-ASCII characters survive. */\n            if (code < 0x80) {\n              char ch = (char)code;\n              writer(ctx, &ch, 1);\n            } else if (code < 0x800) {\n              char b[2];\n              b[0] = (char)(0xC0 | (code >> 6));\n              b[1] = (char)(0x80 | (code & 0x3F));\n              writer(ctx, b, 2);\n            } else if (code < 0x10000) {\n              char b[3];\n              b[0] = (char)(0xE0 | (code >> 12));\n              b[1] = (char)(0x80 | ((code >> 6) & 0x3F));\n              b[2] = (char)(0x80 | (code & 0x3F));\n              writer(ctx, b, 3);\n            } else {\n              char b[4];\n              b[0] = (char)(0xF0 | (code >> 18));\n              b[1] = (char)(0x80 | ((code >> 12) & 0x3F));\n              b[2] = (char)(0x80 | ((code >> 6) & 0x3F));\n              b[3] = (char)(0x80 | (code & 0x3F));\n              writer(ctx, b, 4);\n            }\n            break;\n          }\n          default:\n            /* Unknown spec — emit spec text + type char verbatim\n             * (matches numbl's fallthrough that consumes one arg\n             * and outputs `spec + ch`). The arg has already been\n             * consumed via mtoc__next_slot above. */\n            mtoc__emit_bytes(writer, ctx, spec, spec_len + 1);\n            break;\n        }\n      } else if (c == '\\\\' && i + 1 < fmt_len) {\n        i++;\n        i += mtoc__emit_escape(writer, ctx, fmt.data[i]);\n      } else {\n        writer(ctx, fmt.data + i, 1);\n        i++;\n      }\n    }\n    /* No progress this pass — stop to avoid infinite output. */\n    if (mtoc__iter_consumed(&it) == start_consumed) break;\n  } while (mtoc__iter_has_more(&it));\n}\n",
  "fprintf.h": "/* mtoc runtime helper: fprintf — write formatted text to stdout.\n *\n * Matches numbl's `fprintf` semantics\n * (numbl/src/numbl-core/runtime/specialBuiltins.ts):\n *   - `fprintf(fmt, args...)`         → write to stdout\n *   - `fprintf(1, fmt, args...)`      → write to stdout\n *   - `fprintf(2, fmt, args...)`      → numbl ALSO routes fid=2 to its\n *     single `output` stream; mtoc matches by sending fid=2 to stdout\n *     too (cross-runner parity requires byte-for-byte stdout match).\n *\n * The fid is resolved at lowering (literal 1 or 2 only); the codegen\n * always emits `mtoc_fprintf(stdout, …)`. Other fids are deferred at\n * lowering with an UnsupportedConstruct span.\n *\n * Format engine is shared with sprintf — see `format_engine.h` for the\n * spec set, escape handling, and arg-cycling rules.\n */\n\n#include <stdio.h>\n\nstatic void mtoc__fprintf_writer(void *ctx, const char *bytes, long len) {\n  if (len > 0) fwrite(bytes, 1, (size_t)len, (FILE *)ctx);\n}\n\nstatic void mtoc_fprintf(FILE *f, mtoc_text_view_t fmt,\n                         int nargs, const mtoc_fprintf_arg_t *args) {\n  mtoc__format_walk(mtoc__fprintf_writer, (void *)f, fmt, nargs, args);\n}\n",
  "length.h": "/* mtoc runtime helper: length(t) — numbl's `length`.\n *\n * Returns the largest dim size for a non-empty tensor, or 0 if any\n * dim is 0 (empty tensor). Returned as a double to match every other\n * mtoc value. Generalized over `ndim` so the same body covers 2-D\n * and N-D tensors.\n */\n\nstatic double mtoc_length(mtoc_tensor_t t) {\n  long m = 0;\n  for (int i = 0; i < t.ndim; i++) {\n    if (t.dims[i] == 0) return 0.0;\n    if (t.dims[i] > m) m = t.dims[i];\n  }\n  return (double)m;\n}\n",
  "loop_count.h": "/* mtoc runtime helper: compute the iteration count for a numbl-style\n * `start : step : end` range as a non-negative `long`.\n *\n * numbl evaluates the count as `floor((end - start) / step) + 1` and\n * clamps to zero when the range is empty (start past end with the\n * given step sign). The same formula appears at four codegen sites\n * (for-loops, single-slot slice reads, multi-slot slice setup, slice\n * range writes); routing through one helper centralizes the cast\n * and protects against undefined behavior when `floor(...)` returns\n * a value outside the `long` range.\n *\n * Returns `0` on:\n *   - non-finite floor result (NaN — e.g. step = 0)\n *   - empty range (negative count)\n *   - count that doesn't fit in `long` (clamped rather than aborting:\n *     the user gets an empty range, which is the safest fallback\n *     under static translation — a 1e19-iteration loop is almost\n *     certainly a typo).\n */\n\n#include <limits.h>\n#include <math.h>\n\nstatic long mtoc_loop_count(double start, double end, double step) {\n  double n = floor((end - start) / step) + 1.0;\n  if (!isfinite(n)) return 0;\n  if (n <= 0.0) return 0;\n  /* `(long)n` is undefined when n > LONG_MAX. Compare in double\n   * space to keep the guard well-defined. */\n  if (n > (double)LONG_MAX) return LONG_MAX;\n  return (long)n;\n}\n",
  "max_complex.h": "/* mtoc runtime helper: complex-scalar `max(a, b)`.\n *\n * Mirrors numbl's `complexIsBetter` for the 2-scalar element-wise case:\n *   absA = sqrt(reA*reA + imA*imA);\n *   absB = sqrt(reB*reB + imB*imB);\n *   if (absA != absB) return absA > absB ? a : b;\n *   return atan2(imA, reA) > atan2(imB, reB) ? a : b;\n *\n * See `min_complex.h` for the byte-for-byte rationale.\n */\n\n#include <complex.h>\n#include <math.h>\n\nstatic double _Complex mtoc_max_complex(double _Complex a, double _Complex b) {\n  double aRe = creal(a), aIm = cimag(a);\n  double bRe = creal(b), bIm = cimag(b);\n  double absA = sqrt(aRe * aRe + aIm * aIm);\n  double absB = sqrt(bRe * bRe + bIm * bIm);\n  int pickA;\n  if (absA != absB) pickA = absA > absB;\n  else pickA = atan2(aIm, aRe) > atan2(bIm, bRe);\n  return pickA ? a : b;\n}\n",
  "min_complex.h": "/* mtoc runtime helper: complex-scalar `min(a, b)`.\n *\n * Mirrors numbl's `complexIsBetter` (numbl/src/numbl-core/helpers/reduction/min-max.ts)\n * for the 2-scalar element-wise case:\n *   absA = sqrt(reA*reA + imA*imA);\n *   absB = sqrt(reB*reB + imB*imB);\n *   if (absA != absB) return absA < absB ? a : b;\n *   return atan2(imA, reA) < atan2(imB, reB) ? a : b;\n *\n * Uses `re*re + im*im` (not `hypot`) to match numbl exactly — overflow\n * behavior diverges from `hypot` but mtoc's contract is byte-for-byte\n * cross-runner equivalence.\n */\n\n#include <complex.h>\n#include <math.h>\n\nstatic double _Complex mtoc_min_complex(double _Complex a, double _Complex b) {\n  double aRe = creal(a), aIm = cimag(a);\n  double bRe = creal(b), bIm = cimag(b);\n  double absA = sqrt(aRe * aRe + aIm * aIm);\n  double absB = sqrt(bRe * bRe + bIm * bIm);\n  int pickA;\n  if (absA != absB) pickA = absA < absB;\n  else pickA = atan2(aIm, aRe) < atan2(bIm, bRe);\n  return pickA ? a : b;\n}\n",
  "minmax_all.h": "/* mtoc runtime helpers: 1-arg `min(t)` / `max(t)` over a real tensor.\n *\n * Numbl's `minMaxScanDirect` semantics (numbl/src/numbl-core/helpers/\n * reduction/min-max.ts): NaN elements are skipped. The result is the\n * first non-NaN value beaten by every other non-NaN value; if every\n * element is NaN, the result is NaN.\n *\n * Mtoc's lowerer routes these through static-shape dispatch:\n *   - scalar input → identity (call site never reached).\n *   - vector-like input (≤1 non-singleton axis) → this helper.\n *   - matrix input (≥2 non-singleton axes) → `mtoc_min_real_default`\n *     / `mtoc_max_real_default`.\n *\n * Real-only — complex sibling lives in `minmax_complex_all.h`.\n * Both functions are generated from one macro; only the comparison\n * operator differs (< for min, > for max).\n */\n\n#include <math.h>\n\n/* Helper macro: expand a real min or max linear-scan reduction.\n * CMP is the comparison operator (< or >) that selects the winner. */\n#define MTOC_MINMAX_REAL_ALL(FNAME, CMP)              \\\nstatic double FNAME(mtoc_tensor_t t) {                \\\n  long n = 1;                                         \\\n  for (int i = 0; i < t.ndim; i++) n *= t.dims[i];  \\\n  double m = 0.0;                                     \\\n  int found = 0;                                      \\\n  for (long i = 0; i < n; i++) {                     \\\n    double v = t.real[i];                             \\\n    if (v != v) continue;                             \\\n    if (!found || v CMP m) { m = v; found = 1; }     \\\n  }                                                   \\\n  return found ? m : NAN;                             \\\n}\n\nMTOC_MINMAX_REAL_ALL(mtoc_min_real_all, <)\nMTOC_MINMAX_REAL_ALL(mtoc_max_real_all, >)\n#undef MTOC_MINMAX_REAL_ALL\n",
  "minmax_complex_all.h": "/* mtoc runtime helpers: 1-arg `min(t)` / `max(t)` over a complex tensor.\n *\n * Numbl's complex ordering (numbl/src/numbl-core/helpers/reduction/\n * min-max.ts): primary key is magnitude; ties broken by angle\n * `atan2(im, re)`. An element is skipped if either lane is NaN; if\n * every element is skipped, the result is NaN + 0i.\n *\n * Magnitude is `sqrt(re*re + im*im)` (NOT `hypot`) to match numbl's\n * computation byte-for-byte — `hypot`'s overflow handling diverges\n * on extreme inputs.\n *\n * Both functions are generated from one macro; only the comparison\n * operator differs (< for min, > for max) applied to both magnitude\n * and angle tiebreak.\n */\n\n#include <complex.h>\n#include <math.h>\n\n/* Helper macro: expand a complex min or max linear-scan reduction.\n * CMP is the comparison operator (< or >) applied to magnitude and angle. */\n#define MTOC_MINMAX_COMPLEX_ALL(FNAME, CMP)                      \\\nstatic double _Complex FNAME(mtoc_tensor_t t) {                  \\\n  long n = 1;                                                    \\\n  for (int i = 0; i < t.ndim; i++) n *= t.dims[i];             \\\n  double mRe = 0.0, mIm = 0.0;                                  \\\n  double mMag = 0.0, mAng = 0.0;                                \\\n  int found = 0;                                                 \\\n  for (long i = 0; i < n; i++) {                                \\\n    double re = t.real[i], im = t.imag[i];                      \\\n    if (re != re || im != im) continue;                          \\\n    double mag = sqrt(re * re + im * im);                        \\\n    double ang = atan2(im, re);                                  \\\n    int better;                                                  \\\n    if (!found) {                                                \\\n      better = 1;                                               \\\n    } else if (mag != mMag) {                                   \\\n      better = mag CMP mMag;                                     \\\n    } else {                                                     \\\n      better = ang CMP mAng;                                     \\\n    }                                                            \\\n    if (better) {                                               \\\n      mRe = re; mIm = im; mMag = mag; mAng = ang; found = 1;  \\\n    }                                                            \\\n  }                                                             \\\n  if (!found) return NAN + 0.0 * I;                             \\\n  return mRe + mIm * I;                                         \\\n}\n\nMTOC_MINMAX_COMPLEX_ALL(mtoc_min_complex_all, <)\nMTOC_MINMAX_COMPLEX_ALL(mtoc_max_complex_all, >)\n#undef MTOC_MINMAX_COMPLEX_ALL\n",
  "minmax_complex_default.h": "/* mtoc runtime helpers: min(t) / max(t) along numbl's default\n * reduction dim — first non-singleton axis (1-based). Complex variant.\n *\n * Ordering: primary key magnitude `sqrt(re*re + im*im)`, ties broken\n * by angle `atan2(im, re)`. Matches `minMaxScan` in numbl exactly,\n * including the NaN-skip behavior (an element is skipped if either\n * lane is NaN; an all-skipped fiber outputs NaN + 0i).\n *\n * Scaffold via MTOC_REDUCTION_WALK_COMPLEX (reduction_walk.h).\n * Both functions are generated from one macro; only the comparison\n * operator differs (< for min, > for max) applied to both magnitude\n * and angle tiebreak.\n */\n\n#include <complex.h>\n#include <math.h>\n\n/* Helper macro: expand a complex min or max fiber-walk function.\n * CMP is the comparison operator (< or >) applied to magnitude and angle. */\n#define MTOC_MINMAX_COMPLEX_DEFAULT(FNAME, CMP)                                        \\\n  MTOC_REDUCTION_WALK_COMPLEX(FNAME,                                                   \\\n    n > 0 ? t.real[0] : NAN,                                                          \\\n    n > 0 ? t.imag[0] : 0.0,                                                          \\\n    double mRe = 0.0; double mIm = 0.0; double mMag = 0.0; double mAng = 0.0;        \\\n    int found = 0;,                                                                    \\\n    long idx = slabBase + i + k * inner;                                               \\\n    double re = t.real[idx];                                                           \\\n    double im = t.imag[idx];                                                           \\\n    if (re != re || im != im) continue;                                                \\\n    double mag = sqrt(re * re + im * im);                                              \\\n    double ang = atan2(im, re);                                                        \\\n    int better;                                                                        \\\n    if (!found) better = 1;                                                            \\\n    else if (mag != mMag) better = mag CMP mMag;                                      \\\n    else better = ang CMP mAng;                                                        \\\n    if (better) { mRe = re; mIm = im; mMag = mag; mAng = ang; found = 1; },          \\\n    if (!found) { out.real[out_idx] = NAN; out.imag[out_idx] = 0.0; }                \\\n    else { out.real[out_idx] = mRe; out.imag[out_idx] = mIm; }                       \\\n    out_idx++;                                                                         \\\n  )\n\nMTOC_MINMAX_COMPLEX_DEFAULT(mtoc_min_complex_default, <)\nMTOC_MINMAX_COMPLEX_DEFAULT(mtoc_max_complex_default, >)\n#undef MTOC_MINMAX_COMPLEX_DEFAULT\n",
  "minmax_default.h": "/* mtoc runtime helpers: min(t) / max(t) along numbl's default\n * reduction dim — first non-singleton axis (1-based). Real variant.\n *\n * Used for statically-matrix inputs (≥2 non-singleton axes). NaN\n * elements within a fiber are skipped; if every element in a fiber is\n * NaN, that output slot is NaN — matches `minMaxScan` in numbl/src/\n * numbl-core/helpers/reduction/min-max.ts.\n *\n * See `sum_default.h` for the column-major fiber-walk rationale.\n * Scaffold via MTOC_REDUCTION_WALK_REAL (reduction_walk.h).\n * Both functions are generated from one macro; only the comparison\n * operator differs (< for min, > for max).\n */\n\n#include <math.h>\n\n/* Helper macro: expand a real min or max fiber-walk function.\n * CMP is the comparison operator (< or >) that selects the winner. */\n#define MTOC_MINMAX_REAL_DEFAULT(FNAME, CMP)                                    \\\n  MTOC_REDUCTION_WALK_REAL(FNAME,                                               \\\n    n > 0 ? t.real[0] : NAN,                                                   \\\n    double m = 0.0; int found = 0;,                                             \\\n    double v = t.real[slabBase + i + k * inner];                                \\\n    if (v != v) continue;                                                       \\\n    if (!found || v CMP m) { m = v; found = 1; },                              \\\n    out.real[out_idx++] = found ? m : NAN;                                      \\\n  )\n\nMTOC_MINMAX_REAL_DEFAULT(mtoc_min_real_default, <)\nMTOC_MINMAX_REAL_DEFAULT(mtoc_max_real_default, >)\n#undef MTOC_MINMAX_REAL_DEFAULT\n",
  "mod.h": "/* mtoc runtime helper: MATLAB's `mod(a, b)`.\n *\n * MATLAB semantics: result has the same sign as `b` (or zero). C's\n * `fmod` truncates toward zero, so its result has the same sign as\n * `a`. We adjust by adding `b` whenever the signs differ. By\n * convention `mod(a, 0) == a`.\n */\n\n#include <math.h>\n\nstatic double mtoc_mod(double a, double b) {\n  if (b == 0.0) return a;\n  double r = fmod(a, b);\n  if ((r > 0.0 && b < 0.0) || (r < 0.0 && b > 0.0)) {\n    r += b;\n  }\n  return r;\n}\n",
  "numel.h": "/* mtoc runtime helper: numel(t) — total number of elements.\n *\n * Product across `dims[0..ndim-1]`. The struct invariant is\n * `ndim >= 2` for any tensor mtoc actually constructs (matching\n * numbl's min-2 padding), so the loop always executes at least\n * twice.\n */\n\nstatic double mtoc_numel(mtoc_tensor_t t) {\n  long n = 1;\n  for (int i = 0; i < t.ndim; i++) n *= t.dims[i];\n  return (double)n;\n}\n",
  "reduction_walk.h": "/* mtoc runtime: fiber-walk scaffold macros for axis reductions.\n *\n * These macros generate the full body of a static function that reduces a\n * tensor along numbl's \"default\" dimension (first non-singleton axis,\n * 1-based). They are shared by sum_default.h, sum_complex_default.h,\n * minmax_default.h, and minmax_complex_default.h to avoid repeating the\n * identical outer/inner loop scaffolding in each file.\n *\n * Usage:\n *   MTOC_REDUCTION_WALK_REAL(FNAME, SINGLETON_VAL, INIT_ACC, INNER_BODY, WRITE_OUT)\n *   MTOC_REDUCTION_WALK_COMPLEX(FNAME, SINGLETON_RE, SINGLETON_IM, INIT_ACC, INNER_BODY, WRITE_OUT)\n *\n * Parameters (all must be comma-free unless commas are inside parentheses):\n *   FNAME         - C function name\n *   SINGLETON_VAL - expression for out.real[0] when every dim is 1 (real)\n *   SINGLETON_RE  - expression for out.real[0] in the all-singletons case (complex)\n *   SINGLETON_IM  - expression for out.imag[0] in the all-singletons case (complex)\n *   INIT_ACC      - declarations + initialization of accumulator variables;\n *                   must not contain unprotected commas\n *   INNER_BODY    - body of the innermost k-loop; has slabBase, i, k, inner\n *                   in scope; may use `continue` to skip the current k\n *   WRITE_OUT     - write accumulator to out and advance out_idx\n *\n * The macros are left defined after use (prefixed MTOC_ to avoid collisions);\n * call sites may #undef their own helper macros built on top of these.\n */\n\n/* --- Real output tensor -------------------------------------------------- */\n\n#define MTOC_REDUCTION_WALK_REAL(FNAME, SINGLETON_VAL, INIT_ACC, INNER_BODY, WRITE_OUT) \\\nstatic mtoc_tensor_t FNAME(mtoc_tensor_t t) { \\\n  int dim = 0; \\\n  for (int i = 0; i < t.ndim; i++) { \\\n    if (t.dims[i] > 1) { dim = i + 1; break; } \\\n  } \\\n  if (dim == 0) { \\\n    mtoc_tensor_t out = mtoc_tensor_alloc(1, 1); \\\n    long n = 1; \\\n    for (int i = 0; i < t.ndim; i++) n *= t.dims[i]; \\\n    out.real[0] = SINGLETON_VAL; \\\n    return out; \\\n  } \\\n  long out_dims[MTOC_MAX_NDIM]; \\\n  int out_ndim = t.ndim; \\\n  for (int i = 0; i < t.ndim; i++) out_dims[i] = t.dims[i]; \\\n  out_dims[dim - 1] = 1; \\\n  while (out_ndim > 2 && out_dims[out_ndim - 1] == 1) out_ndim--; \\\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(out_ndim, out_dims); \\\n  long reduceN = t.dims[dim - 1]; \\\n  long inner = 1; \\\n  for (int d = 0; d < dim - 1; d++) inner *= t.dims[d]; \\\n  long slab = inner * reduceN; \\\n  long total = 1; \\\n  for (int d = 0; d < t.ndim; d++) total *= t.dims[d]; \\\n  long outer_count = slab > 0 ? total / slab : 0; \\\n  long out_idx = 0; \\\n  for (long o = 0; o < outer_count; o++) { \\\n    long slabBase = o * slab; \\\n    for (long i = 0; i < inner; i++) { \\\n      INIT_ACC \\\n      for (long k = 0; k < reduceN; k++) { INNER_BODY } \\\n      WRITE_OUT \\\n    } \\\n  } \\\n  return out; \\\n}\n\n/* --- Split-lane complex output tensor ------------------------------------ */\n\n#define MTOC_REDUCTION_WALK_COMPLEX(FNAME, SINGLETON_RE, SINGLETON_IM, INIT_ACC, INNER_BODY, WRITE_OUT) \\\nstatic mtoc_tensor_t FNAME(mtoc_tensor_t t) { \\\n  int dim = 0; \\\n  for (int i = 0; i < t.ndim; i++) { \\\n    if (t.dims[i] > 1) { dim = i + 1; break; } \\\n  } \\\n  if (dim == 0) { \\\n    long _sdims[2] = {1, 1}; \\\n    mtoc_tensor_t out = mtoc_tensor_alloc_nd_complex(2, _sdims); \\\n    long n = 1; \\\n    for (int i = 0; i < t.ndim; i++) n *= t.dims[i]; \\\n    out.real[0] = SINGLETON_RE; \\\n    out.imag[0] = SINGLETON_IM; \\\n    return out; \\\n  } \\\n  long out_dims[MTOC_MAX_NDIM]; \\\n  int out_ndim = t.ndim; \\\n  for (int i = 0; i < t.ndim; i++) out_dims[i] = t.dims[i]; \\\n  out_dims[dim - 1] = 1; \\\n  while (out_ndim > 2 && out_dims[out_ndim - 1] == 1) out_ndim--; \\\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd_complex(out_ndim, out_dims); \\\n  long reduceN = t.dims[dim - 1]; \\\n  long inner = 1; \\\n  for (int d = 0; d < dim - 1; d++) inner *= t.dims[d]; \\\n  long slab = inner * reduceN; \\\n  long total = 1; \\\n  for (int d = 0; d < t.ndim; d++) total *= t.dims[d]; \\\n  long outer_count = slab > 0 ? total / slab : 0; \\\n  long out_idx = 0; \\\n  for (long o = 0; o < outer_count; o++) { \\\n    long slabBase = o * slab; \\\n    for (long i = 0; i < inner; i++) { \\\n      INIT_ACC \\\n      for (long k = 0; k < reduceN; k++) { INNER_BODY } \\\n      WRITE_OUT \\\n    } \\\n  } \\\n  return out; \\\n}\n",
  "rng.h": "/* mtoc PRNG: xoshiro128** seeded via splitmix32, matching numbl's\n * `helpers/prng.ts` byte-for-byte. Used by `rand`, `randn`,\n * `randi`, etc. Numbl's unseeded fallback uses `Math.random()`\n * (V8 xorshift128+, not portable); mtoc instead defaults to a\n * fixed seed of 0 when the user has not called `rng(seed)`. To\n * get cross-runtime byte-identical output, the user's program\n * should call `rng(<seed>)` explicitly before any `rand` /\n * `randn` call.\n *\n * State is a process-wide static: there is no thread safety\n * (mtoc-generated programs are single-threaded). Reseeding via\n * `mtoc_rng_seed` clears the box-Muller spare cache.\n */\n\n#include <math.h>\n#include <stdint.h>\n\nstatic uint32_t mtoc_rng_state[4] = {0, 0, 0, 0};\nstatic int mtoc_rng_initialized = 0;\nstatic double mtoc_bm_spare = 0.0;\nstatic int mtoc_bm_spare_full = 0;\n\nstatic uint32_t mtoc__rotl_u32(uint32_t x, int k) {\n  return (x << k) | (x >> (32 - k));\n}\n\nstatic uint32_t mtoc__splitmix32_step(uint32_t *s) {\n  *s = *s + 0x9e3779b9u;\n  uint32_t z = *s;\n  z = (z ^ (z >> 16)) * 0x85ebca6bu;\n  z = (z ^ (z >> 13)) * 0xc2b2ae35u;\n  return z ^ (z >> 16);\n}\n\n/* Match JS `Math.round(seed) | 0`: round-half-toward-+inf, then\n * truncate to signed 32-bit by reinterpreting as uint32_t. */\nstatic void mtoc_rng_seed(double seed_d) {\n  long rounded = (long)floor(seed_d + 0.5);\n  uint32_t seed_u32 = (uint32_t)(int32_t)rounded;\n  uint32_t s = seed_u32;\n  for (int i = 0; i < 4; i++) {\n    mtoc_rng_state[i] = mtoc__splitmix32_step(&s);\n  }\n  mtoc_rng_initialized = 1;\n  mtoc_bm_spare_full = 0;\n}\n\nstatic uint32_t mtoc__xoshiro128ss(void) {\n  if (!mtoc_rng_initialized) {\n    /* Default seed when the user hasn't called rng() — fixed to 0\n     * so output is deterministic across runs. Numbl's Math.random\n     * fallback is not portable. */\n    mtoc_rng_seed(0.0);\n  }\n  uint32_t result = mtoc__rotl_u32(mtoc_rng_state[1] * 5u, 7) * 9u;\n  uint32_t t = mtoc_rng_state[1] << 9;\n  mtoc_rng_state[2] ^= mtoc_rng_state[0];\n  mtoc_rng_state[3] ^= mtoc_rng_state[1];\n  mtoc_rng_state[1] ^= mtoc_rng_state[2];\n  mtoc_rng_state[0] ^= mtoc_rng_state[3];\n  mtoc_rng_state[2] ^= t;\n  mtoc_rng_state[3] = mtoc__rotl_u32(mtoc_rng_state[3], 11);\n  return result;\n}\n\nstatic double mtoc_rng_random(void) {\n  return (double)mtoc__xoshiro128ss() / 4294967296.0;\n}\n\n/* Marsaglia polar method with a one-element spare cache, mirroring\n * numbl's `boxMullerRandom`. Returns a `N(0, 1)` sample. */\nstatic double mtoc_rng_randn(void) {\n  if (mtoc_bm_spare_full) {\n    mtoc_bm_spare_full = 0;\n    return mtoc_bm_spare;\n  }\n  double u, v, s;\n  do {\n    u = 2.0 * mtoc_rng_random() - 1.0;\n    v = 2.0 * mtoc_rng_random() - 1.0;\n    s = u * u + v * v;\n  } while (s >= 1.0 || s == 0.0);\n  double mul = sqrt((-2.0 * log(s)) / s);\n  mtoc_bm_spare = v * mul;\n  mtoc_bm_spare_full = 1;\n  return u * mul;\n}\n",
  "sign.h": "/* mtoc runtime helper: MATLAB's `sign(x)`.\n *\n * Returns -1 / 0 / +1 according to the sign of x. Unlike `copysign`\n * (which returns ±|x| for any nonzero x), MATLAB's sign is ±1 for\n * nonzero. NaN propagates.\n */\n\n#include <math.h>\n\nstatic double mtoc_sign(double x) {\n  if (isnan(x)) return x;\n  if (x > 0.0) return 1.0;\n  if (x < 0.0) return -1.0;\n  return 0.0;\n}\n",
  "sign_complex.h": "/* mtoc runtime helper: MATLAB's `sign(z)` for complex z.\n *\n * Mirrors numbl's complex sign (numbl/src/numbl-core/interpreter/builtins/math.ts):\n *   mag = hypot(re, im)\n *   if (mag == 0) return 0+0i\n *   return (re/mag) + (im/mag)*i\n *\n * Using `hypot` (rather than `cabs(z)`, which is implementation-defined)\n * keeps the magnitude finite when re*re or im*im would overflow. The\n * 0+0i carve-out matches numbl exactly so a `sign(0+0i)` literal prints\n * \"0\" not \"NaN\" cross-runner.\n */\n\n#include <complex.h>\n#include <math.h>\n\nstatic double _Complex mtoc_sign_complex(double _Complex z) {\n  double re = creal(z);\n  double im = cimag(z);\n  double mag = hypot(re, im);\n  if (mag == 0.0) return 0.0 + 0.0 * I;\n  return (re / mag) + (im / mag) * I;\n}\n",
  "size_dim.h": "/* mtoc runtime helper: size(t, dim) — scalar form returning the\n * length of axis `dim` (1-indexed). For `dim > t.ndim` returns 1\n * (matching numbl's \"implicit trailing singletons\" semantics). For\n * `dim < 1` returns 0 (numbl raises; mtoc opts for the lenient\n * MATLAB-like result rather than aborting).\n */\n\nstatic double mtoc_size_dim(mtoc_tensor_t t, double dim) {\n  long d = (long)dim;\n  if (d < 1) return 0.0;\n  if (d <= t.ndim) return (double)t.dims[d - 1];\n  return 1.0;\n}\n",
  "size_vec.h": "/* mtoc runtime helper: size(t) — returns a 1×max(2,ndim) row vector\n * of dim sizes.\n *\n * Numbl pads ndim to a minimum of 2 in `size`'s output, so a row\n * vector reports `[1 N]` and a column reports `[N 1]` rather than\n * `[N]`. This helper applies the same padding by writing 1 for any\n * axis past `t.ndim`.\n *\n * Returned tensor is owned (`mtoc_tensor_alloc` allocates a fresh\n * `real` buffer); the caller releases it via `mtoc_tensor_assign`\n * / `mtoc_tensor_free` at scope exit.\n */\n\nstatic mtoc_tensor_t mtoc_size_vec(mtoc_tensor_t t) {\n  int n = t.ndim > 2 ? t.ndim : 2;\n  mtoc_tensor_t out = mtoc_tensor_alloc(1, (long)n);\n  for (int i = 0; i < n; i++) {\n    out.real[i] = (double)(i < t.ndim ? t.dims[i] : 1);\n  }\n  return out;\n}\n",
  "sprintf.h": "/* mtoc runtime helper: sprintf — return formatted text as an owned\n * string or char-array, matching numbl's `sprintf`\n * (numbl/src/numbl-core/interpreter/builtins/strings.ts).\n *\n * Numbl returns:\n *   - a `char` value when the format arg is char (single-quoted),\n *   - a `string` value when the format arg is string (double-quoted).\n * mtoc tracks that statically and routes:\n *   - char-typed format → mtoc_sprintf_char → mtoc_char_tensor_t\n *   - string-typed format → mtoc_sprintf_str → mtoc_string_t\n *\n * Both entry points share the format-engine walker via a growable-\n * buffer writer. The returned handle owns its byte buffer; the\n * caller passes it to `mtoc_string_assign` / `mtoc_char_tensor_assign`\n * (or frees it directly via `mtoc_string_free` / `mtoc_char_tensor_free`).\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct {\n  char *data;\n  long len;\n  long cap;\n} mtoc__sprintf_buf_t;\n\nstatic void mtoc__sprintf_writer(void *ctx, const char *bytes, long len) {\n  mtoc__sprintf_buf_t *b = (mtoc__sprintf_buf_t *)ctx;\n  if (len <= 0) return;\n  if (b->len + len > b->cap) {\n    long new_cap = b->cap == 0 ? 64 : b->cap * 2;\n    while (new_cap < b->len + len) new_cap *= 2;\n    char *nb = (char *)realloc(b->data, (size_t)new_cap);\n    if (!nb) {\n      fprintf(stderr, \"mtoc: out of memory in mtoc_sprintf\\n\");\n      abort();\n    }\n    b->data = nb;\n    b->cap = new_cap;\n  }\n  memcpy(b->data + b->len, bytes, (size_t)len);\n  b->len += len;\n}\n\nstatic mtoc_string_t mtoc_sprintf_str(mtoc_text_view_t fmt,\n                                      int nargs,\n                                      const mtoc_fprintf_arg_t *args) {\n  mtoc__sprintf_buf_t b;\n  b.data = (char *)0;\n  b.len = 0;\n  b.cap = 0;\n  mtoc__format_walk(mtoc__sprintf_writer, &b, fmt, nargs, args);\n  mtoc_string_t s;\n  if (b.len == 0) {\n    free(b.data);\n    s.data = (const char *)0;\n    s.len = 0;\n    s.owned = 1;\n    return s;\n  }\n  /* Trim to exact size — sprintf results may be long-lived, so the\n   * trailing slack from doubling has real cost. */\n  char *trimmed = (char *)realloc(b.data, (size_t)b.len);\n  s.data = trimmed ? trimmed : b.data;\n  s.len = b.len;\n  s.owned = 1;\n  return s;\n}\n\nstatic mtoc_char_tensor_t mtoc_sprintf_char(mtoc_text_view_t fmt,\n                                            int nargs,\n                                            const mtoc_fprintf_arg_t *args) {\n  mtoc__sprintf_buf_t b;\n  b.data = (char *)0;\n  b.len = 0;\n  b.cap = 0;\n  mtoc__format_walk(mtoc__sprintf_writer, &b, fmt, nargs, args);\n  mtoc_char_tensor_t c;\n  if (b.len == 0) {\n    free(b.data);\n    c.data = (char *)0;\n    c.rows = 0;\n    c.cols = 0;\n    c.owned = 1;\n    return c;\n  }\n  char *trimmed = (char *)realloc(b.data, (size_t)b.len);\n  c.data = trimmed ? trimmed : b.data;\n  c.rows = 1;\n  c.cols = b.len;\n  c.owned = 1;\n  return c;\n}\n",
  "strcmp_text.h": "/* mtoc runtime helper: strcmp on two text views.\n *\n * Mirrors numbl's `strcmp` semantics for two text values: byte-for-\n * byte equality returns 1.0, else 0.0. Empty × empty match (both\n * zero-length) returns 1.0. The result is a real scalar — numbl\n * exposes a logical, but mtoc represents logicals as `double` so\n * the call site can feed the result straight into arithmetic /\n * `assert` / `disp`. Inputs may be strings or char arrays in any\n * combination; the caller wraps each through\n * `mtoc_text_from_string` / `mtoc_text_from_char_tensor`.\n */\n\n#include <string.h>\n\nstatic double mtoc_strcmp_text(mtoc_text_view_t a, mtoc_text_view_t b) {\n  if (a.len != b.len) return 0.0;\n  if (a.len == 0) return 1.0;\n  return memcmp(a.data, b.data, (size_t)a.len) == 0 ? 1.0 : 0.0;\n}\n",
  "string.h": "/* mtoc string runtime: the C representation for every numbl string\n * value mtoc emits.\n *\n * numbl distinguishes `string` (a scalar handle to a UTF-8 buffer,\n * `length(\"hi\") == 1`) from `char` (a row-vector of code units,\n * `length('hi') == 2`). mtoc supports `string` only — char is\n * rejected at lowering today.\n *\n * Storage:\n *   - `data`  — pointer to the byte sequence. Never NULL once the\n *               value is populated; a fresh `mtoc_string_empty()`\n *               leaves it NULL with len=0 and is treated as the\n *               empty string at the runtime helpers.\n *   - `len`   — length in BYTES (not code points). UTF-8 is the\n *               documented encoding by convention; the runtime never\n *               inspects code points so it works for any byte string.\n *   - `owned` — 1 iff `data` was allocated by an mtoc helper and\n *               must be `free()`-d on disposal. 0 for handles\n *               pointing at a C string literal in `.rodata` (the\n *               common case for `mtoc_string_from_literal`); freeing\n *               those would be undefined behavior, so the free helper\n *               checks the flag.\n *\n * The owned flag means literals are zero-allocation while concat\n * results are heap-allocated; the assignment / scope-exit free path\n * sees both shapes uniformly through `mtoc_string_assign` /\n * `mtoc_string_free`.\n */\n\ntypedef struct {\n  const char *data;\n  long len;\n  int owned;\n} mtoc_string_t;\n",
  "string_alloc_bytes.h": "/* mtoc runtime helper: malloc wrapper for string buffers.\n *\n * Strings allocate `char` buffers (not `double`), so they have their\n * own thin wrapper rather than reusing `mtoc_alloc` (whose return\n * type is `double *`). Aborts with a clear diagnostic on allocation\n * failure so the call site can use the result directly.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic char *mtoc_string_alloc_bytes(long n_bytes) {\n  char *p = (char *)malloc((size_t)n_bytes);\n  if (!p) {\n    fprintf(stderr,\n            \"mtoc: out of memory (mtoc_string_alloc_bytes requested %ld bytes)\\n\",\n            n_bytes);\n    abort();\n  }\n  return p;\n}\n",
  "string_assign.h": "/* mtoc runtime helper: consume-and-replace assignment for strings.\n *\n * Frees `*lhs`'s current backing (only if owned — `mtoc_string_free`\n * checks the flag) and moves `rhs` into place. Codegen guarantees\n * every RHS handed here is either a freshly-allocated owned handle\n * (`mtoc_string_concat` result, `mtoc_string_copy` result) or a\n * literal handle (owned=0 from `mtoc_string_from_literal`); both\n * shapes are valid moves into `*lhs`.\n */\n\nstatic void mtoc_string_assign(mtoc_string_t *lhs, mtoc_string_t rhs) {\n  mtoc_string_free(lhs);\n  *lhs = rhs;\n}\n",
  "string_concat.h": "/* mtoc runtime helper: concatenate two text views into a fresh\n * heap-allocated owned string.\n *\n * Implements numbl's `\"a\" + \"b\" == \"ab\"` semantics, generalized to\n * accept either strings or char arrays on each side (numbl coerces\n * char into string at the `+` boundary; mtoc bridges via the text\n * view at the call site). Both inputs are non-owning views; the\n * returned handle owns its buffer and the caller must pass it to\n * `mtoc_string_assign` (which takes ownership) or\n * `mtoc_string_free`.\n */\n\n#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstatic mtoc_string_t mtoc_string_concat(mtoc_text_view_t a, mtoc_text_view_t b) {\n  long alen = a.len > 0 ? a.len : 0;\n  long blen = b.len > 0 ? b.len : 0;\n  size_t total;\n#if defined(__has_builtin) && __has_builtin(__builtin_add_overflow)\n  if (__builtin_add_overflow((size_t)alen, (size_t)blen, &total)) {\n    fprintf(stderr,\n      \"mtoc: string concat allocation overflow (%ld + %ld bytes)\\n\", alen, blen);\n    abort();\n  }\n#else\n  if ((size_t)alen > SIZE_MAX - (size_t)blen) {\n    fprintf(stderr,\n      \"mtoc: string concat allocation overflow (%ld + %ld bytes)\\n\", alen, blen);\n    abort();\n  }\n  total = (size_t)alen + (size_t)blen;\n#endif\n  mtoc_string_t out;\n  if (total == 0) {\n    out.data = (const char *)0;\n    out.len = 0;\n    out.owned = 1;\n    return out;\n  }\n  char *buf = mtoc_string_alloc_bytes(total);\n  if (alen > 0) memcpy(buf, a.data, (size_t)alen);\n  if (blen > 0) memcpy(buf + alen, b.data, (size_t)blen);\n  out.data = buf;\n  out.len = (long)total;\n  out.owned = 1;\n  return out;\n}\n",
  "string_copy.h": "/* mtoc runtime helper: deep-copy a string handle into a fresh\n * heap buffer.\n *\n * Returns `{malloc'd, len, 1}` — the caller owns the new buffer and\n * is responsible for releasing it (typically via `mtoc_string_assign`,\n * which takes ownership, or `mtoc_string_free`). The byte content is\n * memcpy'd verbatim; encoding is not inspected. Used wherever the\n * lowerer / codegen wants a stand-alone owned copy of a string —\n * notably the `c = a;` assignment path emits\n * `mtoc_string_assign(&c, mtoc_string_copy(a));`.\n */\n\n#include <string.h>\n\nstatic mtoc_string_t mtoc_string_copy(mtoc_string_t s) {\n  mtoc_string_t out;\n  if (s.len <= 0 || s.data == (const char *)0) {\n    /* Empty input → empty output. Avoid a zero-byte malloc, which is\n     * implementation-defined; just return an empty owned handle so\n     * callers' uniform free-on-owned behavior still applies. */\n    out.data = (const char *)0;\n    out.len = 0;\n    out.owned = 1;\n    return out;\n  }\n  char *buf = mtoc_string_alloc_bytes(s.len);\n  memcpy(buf, s.data, (size_t)s.len);\n  out.data = buf;\n  out.len = s.len;\n  out.owned = 1;\n  return out;\n}\n",
  "string_empty.h": "/* mtoc runtime helper: zero-initialized empty string handle.\n *\n * Used at every predeclaration site so a string variable starts in a\n * known state; `mtoc_string_assign` will overwrite it on first\n * assignment. The empty handle is treated as the empty string by the\n * text-view helpers (`mtoc_disp_text` skips the write when `data` is\n * NULL or `len` is 0). `owned` starts as 0 so a stray free of an\n * uninitialized variable is a no-op.\n */\n\nstatic mtoc_string_t mtoc_string_empty(void) {\n  mtoc_string_t s;\n  s.data = (const char *)0;\n  s.len = 0;\n  s.owned = 0;\n  return s;\n}\n",
  "string_free.h": "/* mtoc runtime helper: release a string handle's backing buffer if\n * owned, then reset it to the empty state.\n *\n * The owned flag distinguishes literal-pointing handles (no free) from\n * heap-allocated ones (must free). After this call the struct is in\n * the same shape as `mtoc_string_empty()`, so calling free a second\n * time on the same struct is a safe no-op — useful for the\n * scope-exit safety net at branch merges.\n */\n\n#include <stdlib.h>\n\nstatic void mtoc_string_free(mtoc_string_t *s) {\n  if (s->owned && s->data) {\n    free((void *)s->data);\n  }\n  s->data = (const char *)0;\n  s->len = 0;\n  s->owned = 0;\n}\n",
  "string_from_literal.h": "/* mtoc runtime helper: build a string handle pointing at a C string\n * literal in `.rodata`.\n *\n * Returns `{src, len, 0}` — owned=0 marks the buffer as not heap-\n * allocated, so `mtoc_string_free` will leave it untouched. Callers\n * are expected to pass a pointer to a string with static storage\n * duration (codegen always emits a literal here, so this is safe).\n *\n * `len` should be the byte length excluding the trailing NUL the C\n * literal carries; codegen passes `sizeof(literal) - 1` (literally\n * the source length).\n */\n\nstatic mtoc_string_t mtoc_string_from_literal(const char *src, long len) {\n  mtoc_string_t s;\n  s.data = src;\n  s.len = len;\n  s.owned = 0;\n  return s;\n}\n",
  "sum.h": "/* mtoc runtime helper: sum(t) — reduce a real tensor to a scalar.\n *\n * Walks every element via a single linear loop over the flat buffer.\n * Numbl semantics for a \"reduce to scalar\" call (`firstReduceDim == 0`,\n * i.e. the tensor has at most one non-singleton axis: scalar, row vec,\n * column vec, or any N-D shape whose non-singleton axes collapse to a\n * vector). Generalized over `ndim` so the same body covers vectors and\n * any N-D \"vector-like\" shape.\n *\n * Real-only — the complex sibling lives in `sum_complex.h`. The\n * \"tensor-returning, reduce-along-default-dim\" sibling lives in\n * `sum_default.h` and is used for statically-matrix inputs.\n */\n\nstatic double mtoc_sum(mtoc_tensor_t t) {\n  long n = 1;\n  for (int i = 0; i < t.ndim; i++) n *= t.dims[i];\n  double s = 0.0;\n  for (long i = 0; i < n; i++) s += t.real[i];\n  return s;\n}\n",
  "sum_complex.h": "/* mtoc runtime helper: sum(t) — reduce a complex tensor to a scalar.\n *\n * Sums real and imag lanes independently (addition commutes/distributes\n * over the lane split, so the two lanes are independent for `sum`). Same\n * vector-like-shape contract as `mtoc_sum`; the tensor-returning sibling\n * `mtoc_sum_complex_default` handles statically-matrix inputs.\n */\n\n#include <complex.h>\n\nstatic double _Complex mtoc_sum_complex(mtoc_tensor_t t) {\n  long n = 1;\n  for (int i = 0; i < t.ndim; i++) n *= t.dims[i];\n  double sr = 0.0;\n  double si = 0.0;\n  for (long i = 0; i < n; i++) {\n    sr += t.real[i];\n    si += t.imag[i];\n  }\n  return sr + si * I;\n}\n",
  "sum_complex_default.h": "/* mtoc runtime helper: sum(t) along numbl's default reduction dim,\n * complex variant. See `sum_default.h` for the fiber-walk rationale.\n *\n * Real and imag lanes are summed independently — addition distributes\n * over the lane split (unlike multiplication, which needs the mixed\n * accumulator in `complexProd`).\n *\n * Scaffold via MTOC_REDUCTION_WALK_COMPLEX (reduction_walk.h).\n */\n\nMTOC_REDUCTION_WALK_COMPLEX(mtoc_sum_complex_default,\n  n > 0 ? t.real[0] : 0.0,\n  n > 0 ? t.imag[0] : 0.0,\n  double sr = 0.0; double si = 0.0;,\n  long idx = slabBase + i + k * inner; sr += t.real[idx]; si += t.imag[idx];,\n  out.real[out_idx] = sr; out.imag[out_idx] = si; out_idx++;\n)\n",
  "sum_default.h": "/* mtoc runtime helper: sum(t) along numbl's default reduction dim —\n * the first non-singleton axis of `t` (1-based; matches\n * `firstReduceDim` in numbl/src/numbl-core/helpers/reduction-helpers.ts).\n *\n * Used for statically-matrix inputs: the lowerer routes\n * single-non-singleton-axis (\"vector-like\") shapes through the scalar-\n * returning `mtoc_sum` instead. Here we know at least two axes have a\n * statically-non-singleton size, so the result is a tensor (one axis\n * collapsed to 1, trailing singletons stripped to keep ndim >= 2).\n *\n * Column-major fiber walk: for each `outer` slab of `slab = inner *\n * reduceN` source elements, we sweep `reduceN` values along the reduce\n * axis (stride = inner) and write one accumulated value per inner\n * offset.\n *\n * Scaffold via MTOC_REDUCTION_WALK_REAL (reduction_walk.h).\n */\n\nMTOC_REDUCTION_WALK_REAL(mtoc_sum_default,\n  n > 0 ? t.real[0] : 0.0,\n  double s = 0.0;,\n  s += t.real[slabBase + i + k * inner];,\n  out.real[out_idx++] = s;\n)\n",
  "tensor.h": "/* mtoc tensor runtime: the single C representation for every\n * multi-element tensor mtoc emits.\n *\n * Storage mirrors numbl's split layout — `real` and `imag` are\n * separate Float64 buffers (not interleaved real/imag pairs). For a\n * statically-real tensor, `imag` is NULL: the type system tracks\n * `isComplex` at compile time, so codegen knows up front whether to\n * touch the imag side. There is no runtime branch on `imag != NULL`.\n *\n * Scalars never use this struct — real scalars are bare `double`,\n * complex scalars are `double _Complex`. Anything the type system\n * classifies as multi-element (any axis is `notOne`) gets one\n * `mtoc_tensor_t` value. The data buffers are column-major to match\n * MATLAB / LAPACK.\n *\n * Shape: `ndim` axes with sizes `dims[0..ndim-1]`. The minimum\n * logical ndim is 2 (matching numbl) — a row vector is `{1, n}` and\n * a column vector is `{n, 1}`. `MTOC_MAX_NDIM` caps the inline dims\n * array; tensors with more axes than that are unrepresentable in\n * mtoc today (the static type system enforces this at lowering).\n * Keeping `dims` inline preserves the value-typed semantics of\n * `mtoc_tensor_t` — assign / copy / free do a struct copy and\n * touch only the two heap pointers; the shape rides along for free.\n *\n * Storage is heap-allocated via `mtoc_alloc` at every assignment\n * site. The struct is predeclared with `real = imag = NULL` and\n * `ndim = 0` (no dims populated); the first assignment populates\n * them, and subsequent reassignments at a different runtime shape\n * free the previous buffers and alloc fresh ones. `free` of the\n * predeclared NULLs is a no-op (well-defined by C), so the cleanup\n * path is uniform for first and subsequent assignments alike.\n *\n * The `MTOC_RESTRICT` qualifier on the buffer pointers tells the\n * compiler that distinct `mtoc_tensor_t` values' buffers do not\n * alias each other. It expands to `__restrict__` under GCC/Clang\n * and to nothing on compilers that don't recognize it.\n */\n\n#ifndef MTOC_RESTRICT\n# if defined(__GNUC__) || defined(__clang__)\n#  define MTOC_RESTRICT __restrict__\n# else\n#  define MTOC_RESTRICT\n# endif\n#endif\n\n#ifndef MTOC_MAX_NDIM\n#define MTOC_MAX_NDIM 8\n#endif\n\ntypedef struct {\n  double *MTOC_RESTRICT real;   /* always non-NULL */\n  double *MTOC_RESTRICT imag;   /* NULL iff the tensor is statically real */\n  int  ndim;\n  long dims[MTOC_MAX_NDIM];\n} mtoc_tensor_t;\n",
  "tensor_alloc.h": "/* mtoc runtime helper: allocate an uninitialized real tensor of the\n * given shape. Sets `imag = NULL` (the static-real marker). The\n * returned tensor owns its `real` buffer; caller must release via\n * `mtoc_tensor_free` (or hand it to `mtoc_tensor_assign`, which takes\n * ownership).\n *\n * `mtoc_alloc` aborts on OOM, so the returned struct's `real` is\n * always non-NULL. Used by codegen as the workhorse for elementwise-\n * result construction at every multi-element Assign RHS that isn't a\n * plain tensor literal.\n */\n\n#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic mtoc_tensor_t mtoc_tensor_alloc(long rows, long cols) {\n  mtoc_tensor_t out;\n  size_t n;\n#if defined(__has_builtin) && __has_builtin(__builtin_mul_overflow)\n  if (__builtin_mul_overflow((size_t)rows, (size_t)cols, &n)) {\n    fprintf(stderr,\n      \"mtoc: tensor allocation overflow (%ldx%ld elements)\\n\", rows, cols);\n    abort();\n  }\n#else\n  if ((size_t)cols != 0 && (size_t)rows > (SIZE_MAX / sizeof(double)) / (size_t)cols) {\n    fprintf(stderr,\n      \"mtoc: tensor allocation overflow (%ldx%ld elements)\\n\", rows, cols);\n    abort();\n  }\n  n = (size_t)rows * (size_t)cols;\n#endif\n  out.real = mtoc_alloc(n * sizeof(double));\n  out.imag = NULL;\n  out.ndim = 2;\n  out.dims[0] = rows;\n  out.dims[1] = cols;\n  return out;\n}\n",
  "tensor_alloc_complex.h": "/* mtoc runtime helper: allocate an uninitialized complex tensor of\n * the given shape. Both `real` and `imag` buffers are mallocked; the\n * caller must release via `mtoc_tensor_free` (or hand the struct to\n * `mtoc_tensor_assign`, which takes ownership).\n */\n\n#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic mtoc_tensor_t mtoc_tensor_alloc_complex(long rows, long cols) {\n  mtoc_tensor_t out;\n  size_t n;\n#if defined(__has_builtin) && __has_builtin(__builtin_mul_overflow)\n  if (__builtin_mul_overflow((size_t)rows, (size_t)cols, &n)) {\n    fprintf(stderr,\n      \"mtoc: tensor allocation overflow (%ldx%ld elements)\\n\", rows, cols);\n    abort();\n  }\n#else\n  if ((size_t)cols != 0 && (size_t)rows > (SIZE_MAX / sizeof(double)) / (size_t)cols) {\n    fprintf(stderr,\n      \"mtoc: tensor allocation overflow (%ldx%ld elements)\\n\", rows, cols);\n    abort();\n  }\n  n = (size_t)rows * (size_t)cols;\n#endif\n  out.real = mtoc_alloc(n * sizeof(double));\n  out.imag = mtoc_alloc(n * sizeof(double));\n  out.ndim = 2;\n  out.dims[0] = rows;\n  out.dims[1] = cols;\n  return out;\n}\n",
  "tensor_alloc_nd.h": "/* mtoc runtime helper: allocate an uninitialized real tensor with\n * an arbitrary N-D shape.\n *\n * Used by codegen for builtins that produce a >2-D result (the\n * canonical case is `reshape(A, d1, d2, ..., dN)`). The 2-D fast\n * path lives in `mtoc_tensor_alloc`; this helper is the variadic\n * N-D sibling that copies `ndim` dim sizes from the caller-supplied\n * `dims` array into the struct.\n *\n * `dims` is consumed read-only — the caller may pass a stack\n * `(long[]){…}` compound literal. The returned tensor owns its\n * `real` buffer; `imag` is NULL (the static-real marker). Aborts\n * on `ndim` exceeding the inline `MTOC_MAX_NDIM` cap.\n */\n\n#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic mtoc_tensor_t mtoc_tensor_alloc_nd(int ndim, const long *dims) {\n  if (ndim > MTOC_MAX_NDIM) {\n    fprintf(stderr,\n      \"mtoc: tensor ndim %d exceeds MTOC_MAX_NDIM=%d\\n\", ndim, MTOC_MAX_NDIM);\n    abort();\n  }\n  mtoc_tensor_t out;\n  size_t n = 1;\n  for (int i = 0; i < ndim; i++) {\n    out.dims[i] = dims[i];\n    size_t new_n;\n#if defined(__has_builtin) && __has_builtin(__builtin_mul_overflow)\n    if (__builtin_mul_overflow(n, (size_t)dims[i], &new_n)) {\n      fprintf(stderr,\n        \"mtoc: tensor allocation overflow at dim %d (size %ld)\\n\", i, dims[i]);\n      abort();\n    }\n#else\n    if ((size_t)dims[i] != 0 && n > (SIZE_MAX / sizeof(double)) / (size_t)dims[i]) {\n      fprintf(stderr,\n        \"mtoc: tensor allocation overflow at dim %d (size %ld)\\n\", i, dims[i]);\n      abort();\n    }\n    new_n = n * (size_t)dims[i];\n#endif\n    n = new_n;\n  }\n  out.ndim = ndim;\n  out.real = mtoc_alloc(n * sizeof(double));\n  out.imag = NULL;\n  return out;\n}\n",
  "tensor_alloc_nd_complex.h": "/* mtoc runtime helper: allocate an uninitialized complex tensor\n * with an arbitrary N-D shape. Mirrors `mtoc_tensor_alloc_nd`; both\n * `real` and `imag` lanes get fresh heap buffers.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nstatic mtoc_tensor_t mtoc_tensor_alloc_nd_complex(int ndim, const long *dims) {\n  if (ndim > MTOC_MAX_NDIM) {\n    fprintf(stderr,\n      \"mtoc: tensor ndim %d exceeds MTOC_MAX_NDIM=%d\\n\", ndim, MTOC_MAX_NDIM);\n    abort();\n  }\n  mtoc_tensor_t out;\n  long n = 1;\n  for (int i = 0; i < ndim; i++) {\n    out.dims[i] = dims[i];\n    n *= dims[i];\n  }\n  out.ndim = ndim;\n  out.real = mtoc_alloc((size_t)n * sizeof(double));\n  out.imag = mtoc_alloc((size_t)n * sizeof(double));\n  return out;\n}\n",
  "tensor_assign.h": "/* mtoc runtime helper: consume-and-replace tensor assignment.\n *\n * Frees `*lhs`'s current backing buffers and moves `rhs`'s buffers\n * into `*lhs`. The codegen invariant is that every tensor C-expression\n * on an Assign RHS produces a freshly-owned tensor — a literal, a\n * `mtoc_tensor_copy(...)`, or an elementwise-result built by\n * `mtoc_tensor_alloc(...)` — so the move (rather than a deep copy\n * here) is sound: there is no caller-side reference to the rhs after\n * the call. After the move `rhs.real`/`rhs.imag` hold the old `*lhs`\n * pointers, but rhs is a temporary in the C sense (it's a value\n * passed by copy) and is discarded immediately.\n *\n * Both frees are unconditional — see `mtoc_tensor_free` for why\n * that's safe for both real and complex tensors.\n */\n\n#include <stdlib.h>\n\nstatic void mtoc_tensor_assign(mtoc_tensor_t *lhs, mtoc_tensor_t rhs) {\n  free(lhs->real);\n  free(lhs->imag);\n  *lhs = rhs;\n}\n",
  "tensor_copy.h": "/* mtoc runtime helper: deep-copy a real tensor.\n *\n * The returned tensor owns a fresh `real` buffer (memcpy'd from the\n * source); `imag` is NULL since the caller statically knows the\n * source is real. Used by codegen to honor \"copy on every\n * manipulation\" — every tensor-by-name read and every user-function\n * tensor argument is wrapped in this helper, so the receiver always\n * gets an owned tensor.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_copy(mtoc_tensor_t src) {\n  /* Struct copy preserves ndim and dims; the heap buffer is\n   * replaced with a fresh allocation of the right total size. */\n  mtoc_tensor_t out = src;\n  long n = 1;\n  for (int i = 0; i < src.ndim; i++) n *= src.dims[i];\n  out.real = mtoc_alloc((size_t)n * sizeof(double));\n  out.imag = NULL;\n  memcpy(out.real, src.real, (size_t)n * sizeof(double));\n  return out;\n}\n",
  "tensor_copy_complex.h": "/* mtoc runtime helper: deep-copy a complex tensor.\n *\n * Mirrors `mtoc_tensor_copy` for the complex case — both lanes are\n * mallocked and memcpy'd from the source.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_copy_complex(mtoc_tensor_t src) {\n  /* Struct copy preserves ndim and dims; both lanes get fresh\n   * heap buffers of the right total size. */\n  mtoc_tensor_t out = src;\n  long n = 1;\n  for (int i = 0; i < src.ndim; i++) n *= src.dims[i];\n  out.real = mtoc_alloc((size_t)n * sizeof(double));\n  out.imag = mtoc_alloc((size_t)n * sizeof(double));\n  memcpy(out.real, src.real, (size_t)n * sizeof(double));\n  memcpy(out.imag, src.imag, (size_t)n * sizeof(double));\n  return out;\n}\n",
  "tensor_empty.h": "/* mtoc runtime helper: empty/zero-initialized tensor.\n *\n * Returns the canonical \"no buffers, zero shape\" placeholder used to\n * predeclare every tensor variable. Subsequent assignments overwrite\n * the struct via `mtoc_tensor_assign`, which frees these (NULL)\n * buffers as a no-op and installs the new value.\n */\n\nstatic mtoc_tensor_t mtoc_tensor_empty(void) {\n  mtoc_tensor_t out = { NULL, NULL, 0, {0} };\n  return out;\n}\n",
  "tensor_eye.h": "/* mtoc runtime helper: eye(rows, cols) — 2-D rectangular identity\n * (1s on the main diagonal, 0s elsewhere). Numbl's column-major\n * convention places the (i, i) cell at `real[i + i * rows]`. The\n * 0-arg form `eye()` folds to the scalar literal `1.0` at lowering;\n * the 1-arg form `eye(n)` lowers as `eye(n, n)`. eye is 2-D-only —\n * extending to N-D identities doesn't have an obvious meaning.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_eye_2d(long rows, long cols) {\n  mtoc_tensor_t out = mtoc_tensor_alloc(rows, cols);\n  long n = rows * cols;\n  if (n > 0) memset(out.real, 0, (size_t)n * sizeof(double));\n  long min_rc = rows < cols ? rows : cols;\n  for (long i = 0; i < min_rc; i++) {\n    out.real[i + i * rows] = 1.0;\n  }\n  return out;\n}\n",
  "tensor_free.h": "/* mtoc runtime helper: release a tensor's backing buffers and reset\n * the struct to the empty/zero state.\n *\n * Both `free`s are unconditional. `free(NULL)` is well-defined, so\n * the imag-side free is a no-op for real tensors (where `imag` is\n * always NULL) and a real release for complex tensors. There is no\n * runtime branch on `imag != NULL`. Resetting the struct lets a\n * freed local be safely re-used by `mtoc_tensor_assign` without\n * leaking. Called at every scope-exit site (end of `main`, end of a\n * function body, every `IRStmt.ReturnFromFunction`).\n */\n\n#include <stdlib.h>\n\nstatic void mtoc_tensor_free(mtoc_tensor_t *t) {\n  free(t->real);\n  free(t->imag);\n  t->real = NULL;\n  t->imag = NULL;\n  t->ndim = 0;\n}\n",
  "tensor_from_matrix.h": "/* mtoc runtime helper: build a rows×cols real tensor from a flat\n * column-major data pointer. Codegen reorders the literal's\n * row-major source cells to column-major when it builds the\n * compound-literal array, so layout matches the rest of the runtime.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_from_matrix(\n  const double *data, long rows, long cols\n) {\n  mtoc_tensor_t out = mtoc_tensor_alloc(rows, cols);\n  memcpy(out.real, data, (size_t)(rows * cols) * sizeof(double));\n  return out;\n}\n",
  "tensor_from_matrix_complex.h": "/* mtoc runtime helper: build a rows×cols complex tensor from two\n * flat column-major data pointers. Mirrors `mtoc_tensor_from_matrix`\n * for the complex case.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_from_matrix_complex(\n  const double *re, const double *im, long rows, long cols\n) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_complex(rows, cols);\n  memcpy(out.real, re, (size_t)(rows * cols) * sizeof(double));\n  memcpy(out.imag, im, (size_t)(rows * cols) * sizeof(double));\n  return out;\n}\n",
  "tensor_from_row.h": "/* mtoc runtime helper: build a 1×n real tensor from a flat data\n * pointer. The caller typically passes a C99 compound literal\n * (`(double[]){1.0, 2.0, 3.0}`), which gives the emitted assignment\n * the same one-line shape as the numbl source.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_from_row(const double *data, long n) {\n  mtoc_tensor_t out = mtoc_tensor_alloc(1, n);\n  memcpy(out.real, data, (size_t)n * sizeof(double));\n  return out;\n}\n",
  "tensor_from_row_complex.h": "/* mtoc runtime helper: build a 1×n complex tensor from two flat data\n * pointers (real lane and imaginary lane). Mirrors\n * `mtoc_tensor_from_row` for the complex case; codegen splits each\n * cell into its (re, im) components when materializing a complex\n * tensor literal.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_from_row_complex(\n  const double *re, const double *im, long n\n) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_complex(1, n);\n  memcpy(out.real, re, (size_t)n * sizeof(double));\n  memcpy(out.imag, im, (size_t)n * sizeof(double));\n  return out;\n}\n",
  "tensor_inf.h": "/* mtoc runtime helper: inf(d1, d2, …, dN) — N-D tensor filled with\n * +Infinity. Used for numbl's `inf(...)` / `Inf(...)` constructor\n * builtins.\n */\n\n#include <math.h>\n\nstatic mtoc_tensor_t mtoc_inf_nd(int ndim, const long *dims) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, dims);\n  long n = 1;\n  for (int i = 0; i < ndim; i++) n *= dims[i];\n  for (long i = 0; i < n; i++) out.real[i] = (double)INFINITY;\n  return out;\n}\n",
  "tensor_nan.h": "/* mtoc runtime helper: nan(d1, d2, …, dN) — N-D tensor filled with\n * NaN. Used for numbl's `nan(...)` / `NaN(...)` constructor builtins.\n */\n\n#include <math.h>\n\nstatic mtoc_tensor_t mtoc_nan_nd(int ndim, const long *dims) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, dims);\n  long n = 1;\n  for (int i = 0; i < ndim; i++) n *= dims[i];\n  for (long i = 0; i < n; i++) out.real[i] = NAN;\n  return out;\n}\n",
  "tensor_ones.h": "/* mtoc runtime helper: ones(d1, d2, …, dN) — N-D tensor filled\n * with 1.0. Mirrors `mtoc_zeros_nd` but loop-fills with 1s rather\n * than memset-zeroing.\n */\n\nstatic mtoc_tensor_t mtoc_ones_nd(int ndim, const long *dims) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, dims);\n  long n = 1;\n  for (int i = 0; i < ndim; i++) n *= dims[i];\n  for (long i = 0; i < n; i++) out.real[i] = 1.0;\n  return out;\n}\n",
  "tensor_rand.h": "/* mtoc runtime helper: rand(d1, d2, …, dN) — N-D tensor filled with\n * U(0, 1) samples from the xoshiro128** PRNG. Matches numbl's\n * seeded `rand` byte-for-byte (see `rng.h`). The 0-arg scalar form\n * `rand()` emits `mtoc_rng_random()` directly; this helper is for\n * the variadic form.\n */\n\nstatic mtoc_tensor_t mtoc_rand_nd(int ndim, const long *dims) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, dims);\n  long n = 1;\n  for (int i = 0; i < ndim; i++) n *= dims[i];\n  for (long i = 0; i < n; i++) out.real[i] = mtoc_rng_random();\n  return out;\n}\n",
  "tensor_randn.h": "/* mtoc runtime helper: randn(d1, d2, …, dN) — N-D tensor filled with\n * N(0, 1) samples via the Marsaglia polar method. Mirrors numbl's\n * seeded `randn` byte-for-byte (modulo any host-libm `sqrt` / `log`\n * implementation drift, which is normally bit-identical on\n * IEEE-754 platforms).\n */\n\nstatic mtoc_tensor_t mtoc_randn_nd(int ndim, const long *dims) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, dims);\n  long n = 1;\n  for (int i = 0; i < ndim; i++) n *= dims[i];\n  for (long i = 0; i < n; i++) out.real[i] = mtoc_rng_randn();\n  return out;\n}\n",
  "tensor_reshape.h": "/* mtoc runtime helper: reshape a real tensor to a new N-D shape.\n *\n * Numbl semantics:\n *   - `numel(src)` must equal the product of `new_dims[0..ndim-1]`;\n *     mismatch aborts with a clear diagnostic.\n *   - Column-major data layout is preserved verbatim; the underlying\n *     buffer is byte-identical to `src.real`.\n *\n * Mtoc's ownership model: every tensor expression produces a\n * freshly-owned tensor, so this helper allocates a new buffer and\n * memcpy's the source data. The caller's `src` is independently\n * freed at its scope exit.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_reshape(\n  mtoc_tensor_t src, int ndim, const long *new_dims\n) {\n  long src_n = 1;\n  for (int i = 0; i < src.ndim; i++) src_n *= src.dims[i];\n  long dst_n = 1;\n  for (int i = 0; i < ndim; i++) dst_n *= new_dims[i];\n  if (src_n != dst_n) {\n    fprintf(stderr,\n      \"mtoc: reshape size mismatch - source has %ld elements, target has %ld\\n\",\n      src_n, dst_n);\n    abort();\n  }\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, new_dims);\n  if (src_n > 0) memcpy(out.real, src.real, (size_t)src_n * sizeof(double));\n  return out;\n}\n",
  "tensor_reshape_complex.h": "/* mtoc runtime helper: reshape a complex tensor. Mirrors\n * `mtoc_tensor_reshape` over both `real` and `imag` lanes.\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_tensor_reshape_complex(\n  mtoc_tensor_t src, int ndim, const long *new_dims\n) {\n  long src_n = 1;\n  for (int i = 0; i < src.ndim; i++) src_n *= src.dims[i];\n  long dst_n = 1;\n  for (int i = 0; i < ndim; i++) dst_n *= new_dims[i];\n  if (src_n != dst_n) {\n    fprintf(stderr,\n      \"mtoc: reshape size mismatch - source has %ld elements, target has %ld\\n\",\n      src_n, dst_n);\n    abort();\n  }\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd_complex(ndim, new_dims);\n  if (src_n > 0) {\n    memcpy(out.real, src.real, (size_t)src_n * sizeof(double));\n    memcpy(out.imag, src.imag, (size_t)src_n * sizeof(double));\n  }\n  return out;\n}\n",
  "tensor_transpose.h": "/* mtoc runtime helper: 2-D non-conjugate transpose of a real tensor.\n *\n * Numbl semantics for `A.'` on a numeric matrix: produces a column-\n * major buffer of shape `[cols, rows]`, swapping element positions.\n *\n * Mtoc's static type system rejects N-D transpose at lowering, so\n * this helper assumes a 2-D input (`src.ndim == 2`): `dims[0]` rows ×\n * `dims[1]` cols. Column-major layout means source element (r, c)\n * lives at `src.real[r + c * rows]`; the destination is shaped\n * `[cols, rows]` so element (c, r) of the destination lands at\n * `out.real[c + r * cols]`.\n *\n * Mtoc's ownership model: every tensor expression produces a freshly-\n * owned tensor, so this helper allocates a new buffer. The caller's\n * `src` is independently freed at its scope exit.\n */\n\nstatic mtoc_tensor_t mtoc_tensor_transpose(mtoc_tensor_t src) {\n  long rows = src.dims[0];\n  long cols = src.dims[1];\n  long out_dims[2] = { cols, rows };\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(2, out_dims);\n  for (long r = 0; r < rows; r++) {\n    for (long c = 0; c < cols; c++) {\n      out.real[c + r * cols] = src.real[r + c * rows];\n    }\n  }\n  return out;\n}\n",
  "tensor_transpose_complex.h": "/* mtoc runtime helper: 2-D non-conjugate transpose of a complex tensor.\n *\n * Mirrors `mtoc_tensor_transpose` for the complex case — the real and\n * imag lanes are reordered identically; the imag lane is NOT negated\n * (that is the conjugate-transpose `'` operation, which mtoc doesn't\n * implement yet).\n */\n\nstatic mtoc_tensor_t mtoc_tensor_transpose_complex(mtoc_tensor_t src) {\n  long rows = src.dims[0];\n  long cols = src.dims[1];\n  long out_dims[2] = { cols, rows };\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd_complex(2, out_dims);\n  for (long r = 0; r < rows; r++) {\n    for (long c = 0; c < cols; c++) {\n      long src_idx = r + c * rows;\n      long dst_idx = c + r * cols;\n      out.real[dst_idx] = src.real[src_idx];\n      out.imag[dst_idx] = src.imag[src_idx];\n    }\n  }\n  return out;\n}\n",
  "tensor_zeros.h": "/* mtoc runtime helper: zeros(d1, d2, …, dN) — N-D tensor filled\n * with 0.0. Used by both the 2-D (`zeros(rows, cols)`) and N-D\n * forms; the 1-arg form `zeros(N)` is lowered as a 2-arg call\n * `zeros(N, N)` in codegen, so this helper only needs the dims\n * array. Always returns a freshly-owned tensor.\n */\n\n#include <string.h>\n\nstatic mtoc_tensor_t mtoc_zeros_nd(int ndim, const long *dims) {\n  mtoc_tensor_t out = mtoc_tensor_alloc_nd(ndim, dims);\n  long n = 1;\n  for (int i = 0; i < ndim; i++) n *= dims[i];\n  if (n > 0) memset(out.real, 0, (size_t)n * sizeof(double));\n  return out;\n}\n",
  "text_view.h": "/* mtoc text view: a non-owning (data, len) pair used as the common\n * argument type for runtime helpers that read text byte-for-byte\n * (`disp`, `error`, `assert(_, msg)`, `strcmp`, `string_concat`).\n *\n * numbl distinguishes `char` (1×N row-vector of bytes, single-quoted)\n * from `string` (scalar handle to a UTF-8 buffer, double-quoted), but\n * the helpers above only need to walk the bytes. `mtoc_text_view_t`\n * is what we pass to them; `mtoc_text_from_string` /\n * `mtoc_text_from_char_tensor` are zero-copy adapters the call site\n * uses to bridge either source struct into the view.\n *\n * The view is *non-owning*: the underlying storage stays with the\n * caller (literal in `.rodata`, owned `mtoc_string_t`, owned\n * `mtoc_char_tensor_t`). Helpers that need to *return* text\n * (`mtoc_string_concat`) still produce an owned `mtoc_string_t`.\n */\n\ntypedef struct {\n  const char *data;\n  long len;\n} mtoc_text_view_t;\n\nstatic mtoc_text_view_t mtoc_text_from_string(mtoc_string_t s) {\n  mtoc_text_view_t v;\n  v.data = s.data;\n  v.len = s.len > 0 ? s.len : 0;\n  return v;\n}\n\nstatic mtoc_text_view_t mtoc_text_from_char_tensor(mtoc_char_tensor_t c) {\n  mtoc_text_view_t v;\n  v.data = c.data;\n  v.len = c.rows * c.cols;\n  return v;\n}\n",
  "tic.h": "/* mtoc runtime helpers: tic / toc — wall-clock elapsed time.\n *\n * Mirrors numbl's `tic` / `toc` (numbl/src/numbl-core/interpreter/builtins/time-system.ts\n * and runtime/specialBuiltins.ts). Both keep a process-wide \"last tic\n * start\" so `toc` without an argument reports elapsed since the most\n * recent `tic` call. `toc(handle)` reports elapsed against the value\n * returned by an earlier `tic` (the handle is a number — seconds from\n * the same monotonic origin).\n *\n * Timing source is `clock_gettime(CLOCK_MONOTONIC)` (not wall time,\n * so it isn't affected by system clock adjustments). Numbl uses\n * `performance.now()` which is also monotonic; the absolute values\n * differ between runtimes (numbl's origin is process start, mtoc's is\n * system boot) but elapsed differences match in practice. Tests that\n * compare numbl and mtoc output byte-for-byte must not print the\n * absolute tic value or the elapsed duration — only derived predicates\n * (e.g. `disp(elapsed >= 0)`).\n *\n * The \"print\" variants (`mtoc_toc_print` / `mtoc_toc_print_h`) format\n * with `%.6f` to match numbl's `elapsed.toFixed(6)`.\n */\n\n#include <stdio.h>\n#include <time.h>\n\nstatic double mtoc_tic_state_sec = 0.0;\n\nstatic double mtoc__now_seconds(void) {\n  struct timespec ts;\n  clock_gettime(CLOCK_MONOTONIC, &ts);\n  return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;\n}\n\nstatic double mtoc_tic(void) {\n  mtoc_tic_state_sec = mtoc__now_seconds();\n  return mtoc_tic_state_sec;\n}\n\nstatic double mtoc_toc(void) {\n  return mtoc__now_seconds() - mtoc_tic_state_sec;\n}\n\nstatic double mtoc_toc_h(double h) {\n  return mtoc__now_seconds() - h;\n}\n\nstatic void mtoc_toc_print(void) {\n  double elapsed = mtoc__now_seconds() - mtoc_tic_state_sec;\n  printf(\"Elapsed time is %.6f seconds.\\n\", elapsed);\n}\n\nstatic void mtoc_toc_print_h(double h) {\n  double elapsed = mtoc__now_seconds() - h;\n  printf(\"Elapsed time is %.6f seconds.\\n\", elapsed);\n}\n",
};
